function useTokenStyles() {
  useEffect(() => {
    if (document.getElementById("agencyos-tokens")) return;
    const el = document.createElement("style");
    el.id = "agencyos-tokens";
    el.textContent = TOKEN_CSS;
    document.head.appendChild(el);
  }, []);
}

