// ─── Calendario ──────────────────────────────────────────────────────────────

type CalEvent = { id: number; date: string; time: string; title: string; kind: "reunion" | "entrega" | "pago" | "campana" };

const CAL_KINDS: Record<CalEvent["kind"], { label: string; color: string }> = {
  reunion: { label: "Reunión", color: "#3B82F6" },
  entrega: { label: "Entrega", color: "#0F9D6E" },
  pago:    { label: "Pago",    color: "#F59E0B" },
  campana: { label: "Campaña", color: "#8B5CF6" },
};

const pad2 = (n: number) => String(n).padStart(2, "0");
const dKey = (y: number, m: number, d: number) => `${y}-${pad2(m + 1)}-${pad2(d)}`;

function seedEvents(): CalEvent[] {
  const t = new Date();
  const y = t.getFullYear(), m = t.getMonth(), d = t.getDate();
  const at = (off: number) => { const x = new Date(y, m, d + off); return dKey(x.getFullYear(), x.getMonth(), x.getDate()); };
  return [
    { id: 1, date: at(0),  time: "10:00", title: "Revisión semanal de campañas",    kind: "reunion" },
    { id: 2, date: at(0),  time: "12:30", title: "Llamada con Clínica Lumina",      kind: "reunion" },
    { id: 3, date: at(0),  time: "16:00", title: "Kickoff sitio web InmoBienes",    kind: "reunion" },
    { id: 4, date: at(2),  time: "09:00", title: "Entrega de reporte SEO — FashionMX", kind: "entrega" },
    { id: 5, date: at(3),  time: "11:00", title: "Vence pago de InmoBienes",        kind: "pago" },
    { id: 6, date: at(5),  time: "08:00", title: "Lanzamiento campaña Meta — TechCorp", kind: "campana" },
    { id: 7, date: at(7),  time: "15:00", title: "Renovación de contrato BellaVita", kind: "reunion" },
    { id: 8, date: at(9),  time: "10:00", title: "Entrega de diseño web — LogísticaMX", kind: "entrega" },
    { id: 9, date: at(12), time: "12:00", title: "Cierre de mes: facturación",      kind: "pago" },
    { id: 10, date: at(-3), time: "17:00", title: "Revisión de ROAS Google Ads",     kind: "campana" },
  ];
}

function CalendarView() {
  const today = new Date();
  const [cursor, setCursor] = useState({ y: today.getFullYear(), m: today.getMonth() });
  const [sel, setSel] = useState(dKey(today.getFullYear(), today.getMonth(), today.getDate()));
  const [events, setEvents] = useState<CalEvent[]>(seedEvents);
  const [form, setForm] = useState({ title: "", time: "10:00", kind: "reunion" as CalEvent["kind"] });
  const [filter, setFilter] = useState<"all" | CalEvent["kind"]>("all");

  const monthName = new Date(cursor.y, cursor.m, 1).toLocaleDateString("es-MX", { month: "long", year: "numeric" });
  const first = new Date(cursor.y, cursor.m, 1);
  const offset = (first.getDay() + 6) % 7; // semana empieza en lunes
  const daysInMonth = new Date(cursor.y, cursor.m + 1, 0).getDate();
  const cells: (number | null)[] = [...Array(offset).fill(null), ...Array.from({ length: daysInMonth }, (_, i) => i + 1)];
  while (cells.length % 7 !== 0) cells.push(null);

  const visible = events.filter(e => filter === "all" || e.kind === filter);
  const byDay = (k: string) => visible.filter(e => e.date === k).sort((a, b) => a.time.localeCompare(b.time));
  const todayKey = dKey(today.getFullYear(), today.getMonth(), today.getDate());
  const selEvents = byDay(sel);
  const selLabel = new Date(sel + "T00:00:00").toLocaleDateString("es-MX", { weekday: "long", day: "numeric", month: "long" });

  const move = (delta: number) => setCursor(c => { const d = new Date(c.y, c.m + delta, 1); return { y: d.getFullYear(), m: d.getMonth() }; });
  const goToday = () => { setCursor({ y: today.getFullYear(), m: today.getMonth() }); setSel(todayKey); };
  const add = () => {
    if (!form.title.trim()) return;
    setEvents(es => [...es, { id: Date.now(), date: sel, time: form.time, title: form.title.trim(), kind: form.kind }]);
    setForm({ ...form, title: "" });
  };
  const remove = (id: number) => setEvents(es => es.filter(e => e.id !== id));

  return (
    <div className="grid lg:grid-cols-3 gap-4">
      <Card className="lg:col-span-2 p-5">
        <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
          <div className="flex items-center gap-2">
            <button onClick={() => move(-1)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronLeft size={14} className="text-muted-foreground" /></button>
            <button onClick={() => move(1)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronRight size={14} className="text-muted-foreground" /></button>
            <h2 className="text-base font-semibold text-foreground ml-1 first-letter:uppercase">{monthName}</h2>
          </div>
          <div className="flex items-center gap-2">
            <select value={filter} onChange={e => setFilter(e.target.value as any)} className="bg-secondary/40 border border-border rounded-lg px-2.5 py-1.5 text-xs text-foreground focus:outline-none">
              <option value="all">Todos los tipos</option>
              {Object.entries(CAL_KINDS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
            </select>
            <button onClick={goToday} className="px-3 py-1.5 rounded-lg border border-border text-xs text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors">Hoy</button>
          </div>
        </div>

        <div className="grid grid-cols-7 gap-px mb-1">
          {["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map(d => (
            <div key={d} className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider text-center py-1.5">{d}</div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-1">
          {cells.map((day, i) => {
            if (day === null) return <div key={i} className="min-h-[76px] rounded-lg bg-secondary/10" />;
            const k = dKey(cursor.y, cursor.m, day);
            const evs = byDay(k);
            const isToday = k === todayKey, isSel = k === sel;
            return (
              <button key={i} onClick={() => setSel(k)}
                className={`min-h-[76px] text-left rounded-lg p-1.5 border transition-colors ${isSel ? "border-[#0F9D6E] bg-[#0F9D6E]/10" : "border-border bg-secondary/20 hover:bg-secondary/50"}`}>
                <div className={`text-xs font-medium w-5 h-5 flex items-center justify-center rounded-full ${isToday ? "bg-[#0F9D6E] text-white" : "text-foreground"}`}>{day}</div>
                <div className="mt-1 space-y-0.5">
                  {evs.slice(0, 2).map(e => (
                    <div key={e.id} className="flex items-center gap-1 text-[10px] leading-tight text-muted-foreground truncate">
                      <span className="w-1.5 h-1.5 rounded-full shrink-0" style={{ backgroundColor: CAL_KINDS[e.kind].color }} />
                      <span className="truncate">{e.title}</span>
                    </div>
                  ))}
                  {evs.length > 2 && <div className="text-[10px] text-muted-foreground">+{evs.length - 2} más</div>}
                </div>
              </button>
            );
          })}
        </div>

        <div className="flex flex-wrap gap-4 mt-4">
          {Object.entries(CAL_KINDS).map(([k, v]) => (
            <div key={k} className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <span className="w-2 h-2 rounded-full" style={{ backgroundColor: v.color }} />{v.label}
            </div>
          ))}
        </div>
      </Card>

      <Card className="p-5 self-start">
        <h2 className="text-sm font-semibold text-foreground first-letter:uppercase">{selLabel}</h2>
        <p className="text-xs text-muted-foreground mb-4">{selEvents.length} evento{selEvents.length === 1 ? "" : "s"}</p>
        <div className="space-y-2 mb-5">
          {selEvents.length === 0 && <p className="text-xs text-muted-foreground py-4 text-center border border-dashed border-border rounded-lg">Sin eventos este día</p>}
          {selEvents.map(e => (
            <div key={e.id} className="flex items-start gap-3 p-3 bg-secondary/30 rounded-lg border border-border">
              <span className="w-1 self-stretch rounded-full" style={{ backgroundColor: CAL_KINDS[e.kind].color }} />
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium text-foreground leading-tight">{e.title}</div>
                <div className="text-xs text-muted-foreground mt-0.5"><span className="font-mono">{e.time}</span> · {CAL_KINDS[e.kind].label}</div>
              </div>
              <button onClick={() => remove(e.id)} title="Eliminar" className="p-1 rounded hover:bg-secondary transition-colors"><Trash2 size={12} className="text-muted-foreground" /></button>
            </div>
          ))}
        </div>

        <div className="border-t border-border pt-4 space-y-2.5">
          <div className="text-xs font-semibold text-foreground">Nuevo evento</div>
          <input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} onKeyDown={e => e.key === "Enter" && add()}
            placeholder="Título del evento" className="w-full bg-secondary/40 border border-border rounded-lg px-3 py-2 text-sm text-foreground placeholder-muted-foreground focus:outline-none focus:border-[#0F9D6E]" />
          <div className="grid grid-cols-2 gap-2">
            <input type="time" value={form.time} onChange={e => setForm({ ...form, time: e.target.value })} className="bg-secondary/40 border border-border rounded-lg px-3 py-2 text-sm text-foreground focus:outline-none focus:border-[#0F9D6E]" />
            <select value={form.kind} onChange={e => setForm({ ...form, kind: e.target.value as CalEvent["kind"] })} className="bg-secondary/40 border border-border rounded-lg px-3 py-2 text-sm text-foreground focus:outline-none focus:border-[#0F9D6E]">
              {Object.entries(CAL_KINDS).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
            </select>
          </div>
          <button onClick={add} className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-[#0F9D6E] hover:bg-[#0B7C57] text-white rounded-lg text-sm font-medium transition-colors">
            <Plus size={14} />Agregar evento
          </button>
        </div>
      </Card>
    </div>
  );
}

const HOME_TABS = [
  { id: "resumen",   label: "Resumen",   icon: HomeIcon },
  { id: "calendario", label: "Calendario", icon: Calendar },
  { id: "ideas",     label: "Ideas",     icon: Sparkles },
  { id: "mensajes",  label: "Mensajes",  icon: MessageSquare },
  { id: "analytics", label: "Analytics", icon: TrendingUp },
  { id: "tableros",  label: "Tableros",  icon: LayoutDashboard },
  { id: "reportes",  label: "Reportes",  icon: FileText },
  { id: "links",     label: "Links",     icon: Link2 },
] as const;

function HomeModule() {
  const [tab, setTab] = useState<string>("calendario");
  const cur = HOME_TABS.find(t => t.id === tab)!;
  return (
    <div>
      <div className="mb-5 overflow-x-auto">
        <div className="inline-flex items-center gap-1 p-1.5 rounded-2xl bg-card border border-border">
          {HOME_TABS.map(t => {
            const on = t.id === tab;
            return (
              <button key={t.id} onClick={() => setTab(t.id)}
                className={`flex items-center gap-2 px-3.5 py-2 rounded-xl text-sm font-medium whitespace-nowrap transition-colors border ${on ? "border-[#0F9D6E] bg-[#0F9D6E]/10 text-[#0F9D6E]" : "border-transparent text-muted-foreground hover:text-foreground hover:bg-secondary/50"}`}>
                <t.icon size={15} />{t.label}
              </button>
            );
          })}
        </div>
      </div>
      {tab === "resumen" && <HomeSummary />}
      {tab === "calendario" && <CalendarView />}
      {tab !== "resumen" && tab !== "calendario" && (
        <Card className="p-10 text-center">
          <div className="w-10 h-10 rounded-xl bg-secondary mx-auto mb-3 flex items-center justify-center"><cur.icon size={18} className="text-muted-foreground" /></div>
          <h2 className="text-sm font-semibold text-foreground">{cur.label}</h2>
          <p className="text-xs text-muted-foreground mt-1">Esta sección estará disponible próximamente.</p>
        </Card>
      )}
    </div>
  );
}

// ─── Mi espacio (tareas) ─────────────────────────────────────────────────────

type TStatus = "todo" | "doing" | "review" | "done";
type TPriority = "high" | "med" | "low";
type Task = { id: number; title: string; desc: string; status: TStatus; priority: TPriority; start: string; due: string; client: string };

const T_STATUS: { id: TStatus; label: string; color: string }[] = [
  { id: "todo",   label: "Por hacer",   color: "#64748B" },
  { id: "doing",  label: "En progreso", color: "#3B82F6" },
  { id: "review", label: "En revisión", color: "#F59E0B" },
  { id: "done",   label: "Hecho",       color: "#10B981" },
];
const T_PRIORITY: Record<TPriority, { label: string; color: string; rank: number }> = {
  high: { label: "Alta",  color: "#EF4444", rank: 0 },
  med:  { label: "Media", color: "#F59E0B", rank: 1 },
  low:  { label: "Baja",  color: "#64748B", rank: 2 },
};
const statusOf = (s: TStatus) => T_STATUS.find(x => x.id === s)!;

const isoOf = (d: Date) => dKey(d.getFullYear(), d.getMonth(), d.getDate());
const parseISO = (s: string) => new Date(s + "T00:00:00");
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
const shortDate = (s: string) => parseISO(s).toLocaleDateString("es-MX", { day: "numeric", month: "short" });

const TASKS_KEY = "agencyos-myspace-tasks";

function seedTasks(): Task[] {
  const t = new Date();
  const at = (n: number) => isoOf(addDays(t, n));
  return [
    { id: 1, title: "Reporte mensual SEO — FashionMX",       desc: "Consolidar posiciones, tráfico orgánico y conversiones.", status: "doing",  priority: "high", start: at(-2), due: at(2),  client: "FashionMX" },
    { id: 2, title: "Cobranza pago vencido",                 desc: "Contactar a LogísticaMX y confirmar fecha de pago.",       status: "todo",   priority: "high", start: at(0),  due: at(1),  client: "LogísticaMX" },
    { id: 3, title: "Propuesta de renovación",               desc: "Preparar propuesta con nuevos alcances para BellaVita.",   status: "todo",   priority: "med",  start: at(1),  due: at(6),  client: "BellaVita Spa" },
    { id: 4, title: "Optimizar campañas Meta",               desc: "Revisar audiencias y creativos de bajo rendimiento.",      status: "review", priority: "med",  start: at(-4), due: at(0),  client: "TechCorp MX" },
    { id: 5, title: "Diseño de landing de promoción",        desc: "Maquetar landing para campaña de fin de año.",             status: "doing",  priority: "med",  start: at(0),  due: at(8),  client: "InmoBienes" },
    { id: 6, title: "Auditoría técnica del sitio",           desc: "Core Web Vitals, indexación y errores 404.",               status: "todo",   priority: "low",  start: at(3),  due: at(11), client: "Clínica Lumina" },
    { id: 7, title: "Actualizar banco de keywords",          desc: "Agregar 40 nuevas keywords de intención transaccional.",   status: "done",   priority: "low",  start: at(-9), due: at(-5), client: "InmoBienes" },
    { id: 8, title: "Kickoff de proyecto ERP",               desc: "Reunión inicial y definición de entregables.",             status: "done",   priority: "high", start: at(-12), due: at(-8), client: "LogísticaMX" },
  ];
}

function useTasks() {
  const [tasks, setTasks] = useState<Task[]>(() => {
    try { const raw = localStorage.getItem(TASKS_KEY); if (raw) return JSON.parse(raw); } catch {}
    return seedTasks();
  });
  useEffect(() => { try { localStorage.setItem(TASKS_KEY, JSON.stringify(tasks)); } catch {} }, [tasks]);
  return [tasks, setTasks] as const;
}

function PriorityDot({ p }: { p: TPriority }) {
  return <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground"><span className="w-2 h-2 rounded-full" style={{ backgroundColor: T_PRIORITY[p].color }} />{T_PRIORITY[p].label}</span>;
}
function StatusPill({ s }: { s: TStatus }) {
  const st = statusOf(s);
  return <span className="inline-flex items-center gap-1.5 text-xs px-2 py-0.5 rounded-full border" style={{ color: st.color, borderColor: st.color + "44", backgroundColor: st.color + "14" }}>{st.label}</span>;
}

function TaskModal({ open, task, onClose, onSave, onDelete }: {
  open: boolean; task: Task | null; onClose: () => void; onSave: (t: Task) => void; onDelete: (id: number) => void;
}) {
  const [f, setF] = useState<Task | null>(task);
  useEffect(() => { setF(task); }, [task, open]);
  if (!open || !f) return null;
  const isNew = !f.id;
  const valid = f.title.trim().length > 0;
  const set = (patch: Partial<Task>) => setF({ ...f, ...patch });
  return (
    <Modal open={open} onClose={onClose} size="md" title={isNew ? "Nueva tarea" : "Editar tarea"} subtitle="Mi espacio"
      footer={<>
        {!isNew && <button onClick={() => { onDelete(f.id); onClose(); }} className="mr-auto flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm text-red-400 hover:bg-red-500/10 transition-colors"><Trash2 size={13} />Eliminar</button>}
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
        <button disabled={!valid} onClick={() => { onSave({ ...f, title: f.title.trim() }); onClose(); }}
          className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#0F9D6E] hover:bg-[#0B7C57] disabled:opacity-40 transition-colors">{isNew ? "Crear tarea" : "Guardar"}</button>
      </>}>
      <div className="p-6 space-y-4">
        <Field label="Título"><input autoFocus value={f.title} onChange={e => set({ title: e.target.value })} className={inputCls} placeholder="¿Qué hay que hacer?" /></Field>
        <Field label="Descripción"><textarea value={f.desc} onChange={e => set({ desc: e.target.value })} rows={3} className={inputCls} placeholder="Detalles opcionales" /></Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Estado">
            <select value={f.status} onChange={e => set({ status: e.target.value as TStatus })} className={inputCls}>
              {T_STATUS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
            </select>
          </Field>
          <Field label="Prioridad">
            <select value={f.priority} onChange={e => set({ priority: e.target.value as TPriority })} className={inputCls}>
              {Object.entries(T_PRIORITY).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
            </select>
          </Field>
          <Field label="Inicio"><input type="date" value={f.start} onChange={e => set({ start: e.target.value, due: e.target.value > f.due ? e.target.value : f.due })} className={inputCls} /></Field>
          <Field label="Vencimiento"><input type="date" value={f.due} min={f.start} onChange={e => set({ due: e.target.value })} className={inputCls} /></Field>
        </div>
        <Field label="Cliente / proyecto">
          <select value={f.client} onChange={e => set({ client: e.target.value })} className={inputCls}>
            <option value="">Sin cliente</option>
            {CLIENTS.map(c => <option key={c.id} value={c.company}>{c.company}</option>)}
          </select>
        </Field>
      </div>
    </Modal>
  );
}

const MS_VIEWS = [
  { id: "cards",    label: "Cards",    icon: LayoutGrid },
  { id: "kanban",   label: "Kanban",   icon: Columns3 },
  { id: "table",    label: "Tabla",    icon: TableIcon },
  { id: "calendar", label: "Calendario", icon: Calendar },
  { id: "timeline", label: "Timeline", icon: List },
] as const;

function MySpaceModule() {
  const [tasks, setTasks] = useTasks();
  const [view, setView] = useState<string>("cards");
  const [q, setQ] = useState("");
  const [prio, setPrio] = useState<"all" | TPriority>("all");
  const [editing, setEditing] = useState<Task | null>(null);
  const [open, setOpen] = useState(false);

  const todayISO = isoOf(new Date());
  const blank = (patch: Partial<Task> = {}): Task => ({ id: 0, title: "", desc: "", status: "todo", priority: "med", start: todayISO, due: todayISO, client: "", ...patch });
  const openNew = (patch: Partial<Task> = {}) => { setEditing(blank(patch)); setOpen(true); };
  const openEdit = (t: Task) => { setEditing(t); setOpen(true); };
  const save = (t: Task) => setTasks(ts => t.id ? ts.map(x => x.id === t.id ? t : x) : [...ts, { ...t, id: Date.now() }]);
  const del = (id: number) => setTasks(ts => ts.filter(x => x.id !== id));
  const patch = (id: number, p: Partial<Task>) => setTasks(ts => ts.map(x => x.id === id ? { ...x, ...p } : x));

  const list = tasks.filter(t =>
    (prio === "all" || t.priority === prio) &&
    (!q.trim() || (t.title + " " + t.client + " " + t.desc).toLowerCase().includes(q.trim().toLowerCase())));
  const doneN = tasks.filter(t => t.status === "done").length;
  const lateN = tasks.filter(t => t.status !== "done" && t.due < todayISO).length;

  const common = { tasks: list, openEdit, openNew, patch, del, todayISO };

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-3 mb-5">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Mi espacio</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{tasks.length} tareas · {doneN} hechas{lateN ? ` · ${lateN} atrasada${lateN === 1 ? "" : "s"}` : ""}</p>
        </div>
        <button onClick={() => openNew()} className="flex items-center gap-2 px-4 py-2 bg-[#0F9D6E] hover:bg-[#0B7C57] text-white rounded-lg text-sm font-medium transition-colors">
          <Plus size={14} />Nueva tarea
        </button>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 mb-5">
        <div className="overflow-x-auto">
          <div className="inline-flex items-center gap-1 p-1 rounded-xl bg-card border border-border">
            {MS_VIEWS.map(v => {
              const on = v.id === view;
              return (
                <button key={v.id} onClick={() => setView(v.id)}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${on ? "bg-[#0F9D6E]/15 text-[#0F9D6E]" : "text-muted-foreground hover:text-foreground hover:bg-secondary/50"}`}>
                  <v.icon size={14} />{v.label}
                </button>
              );
            })}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="relative">
            <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar tarea…" className="pl-8 pr-3 py-1.5 w-48 bg-secondary/40 border border-border rounded-lg text-sm text-foreground placeholder-muted-foreground focus:outline-none focus:border-[#0F9D6E]" />
          </div>
          <select value={prio} onChange={e => setPrio(e.target.value as any)} className="bg-secondary/40 border border-border rounded-lg px-2.5 py-1.5 text-sm text-foreground focus:outline-none">
            <option value="all">Toda prioridad</option>
            {Object.entries(T_PRIORITY).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
          </select>
        </div>
      </div>

      {view === "cards" && <TaskCards {...common} />}
      {view === "kanban" && <TaskKanban {...common} />}
      {view === "table" && <TaskTable {...common} />}
      {view === "calendar" && <TaskCalendar {...common} />}
      {view === "timeline" && <TaskTimeline {...common} />}

      <TaskModal open={open} task={editing} onClose={() => setOpen(false)} onSave={save} onDelete={del} />
    </div>
  );
}

type VP = { tasks: Task[]; openEdit: (t: Task) => void; openNew: (p?: Partial<Task>) => void; patch: (id: number, p: Partial<Task>) => void; del: (id: number) => void; todayISO: string };

function Empty({ onNew }: { onNew: () => void }) {
  return (
    <Card className="p-10 text-center">
      <p className="text-sm text-muted-foreground mb-3">No hay tareas que coincidan.</p>
      <button onClick={onNew} className="inline-flex items-center gap-2 px-4 py-2 bg-[#0F9D6E] text-white rounded-lg text-sm font-medium"><Plus size={14} />Crear tarea</button>
    </Card>
  );
}

function TaskCards({ tasks, openEdit, openNew, patch, todayISO }: VP) {
  if (!tasks.length) return <Empty onNew={() => openNew()} />;
  return (
    <div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">
      {tasks.map(t => {
        const late = t.status !== "done" && t.due < todayISO;
        return (
          <Card key={t.id} className="p-4 flex flex-col gap-3 hover:border-[#0F9D6E]/40 transition-colors">
            <div className="flex items-start justify-between gap-2">
              <button onClick={() => openEdit(t)} className={`text-left text-sm font-semibold leading-snug ${t.status === "done" ? "line-through text-muted-foreground" : "text-foreground"} hover:text-[#0F9D6E]`}>{t.title}</button>
              <span className="w-2 h-2 rounded-full mt-1.5 shrink-0" title={`Prioridad ${T_PRIORITY[t.priority].label}`} style={{ backgroundColor: T_PRIORITY[t.priority].color }} />
            </div>
            {t.desc && <p className="text-xs text-muted-foreground leading-relaxed line-clamp-2">{t.desc}</p>}
            <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
              {t.client && <span className="px-2 py-0.5 rounded bg-secondary/60 border border-border">{t.client}</span>}
              <span className={`flex items-center gap-1 ${late ? "text-red-400" : ""}`}><Calendar size={11} />{shortDate(t.due)}{late ? " · atrasada" : ""}</span>
            </div>
            <div className="flex items-center justify-between mt-auto pt-3 border-t border-border">
              <StatusPill s={t.status} />
              <select value={t.status} onChange={e => patch(t.id, { status: e.target.value as TStatus })} className="bg-transparent text-xs text-muted-foreground border border-border rounded-md px-1.5 py-1 focus:outline-none">
                {T_STATUS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
              </select>
            </div>
          </Card>
        );
      })}
    </div>
  );
}

function TaskKanban({ tasks, openEdit, openNew, patch, todayISO }: VP) {
  const [dragId, setDragId] = useState<number | null>(null);
  const [over, setOver] = useState<TStatus | null>(null);
  return (
    <div className="grid md:grid-cols-2 xl:grid-cols-4 gap-4 items-start">
      {T_STATUS.map(col => {
        const items = tasks.filter(t => t.status === col.id);
        return (
          <div key={col.id}
            onDragOver={e => { e.preventDefault(); setOver(col.id); }}
            onDragLeave={() => setOver(o => o === col.id ? null : o)}
            onDrop={e => { e.preventDefault(); if (dragId) patch(dragId, { status: col.id }); setDragId(null); setOver(null); }}
            className={`rounded-xl border p-3 transition-colors ${over === col.id ? "border-[#0F9D6E] bg-[#0F9D6E]/5" : "border-border bg-secondary/20"}`}>
            <div className="flex items-center justify-between mb-3 px-1">
              <div className="flex items-center gap-2">
                <span className="w-2 h-2 rounded-full" style={{ backgroundColor: col.color }} />
                <span className="text-sm font-semibold text-foreground">{col.label}</span>
                <span className="text-xs text-muted-foreground">{items.length}</span>
              </div>
              <button onClick={() => openNew({ status: col.id })} title="Añadir tarea" className="p-1 rounded hover:bg-secondary transition-colors"><Plus size={13} className="text-muted-foreground" /></button>
            </div>
            <div className="space-y-2.5 min-h-[40px]">
              {items.map(t => {
                const late = t.status !== "done" && t.due < todayISO;
                return (
                  <div key={t.id} draggable onDragStart={() => setDragId(t.id)} onDragEnd={() => { setDragId(null); setOver(null); }}
                    onClick={() => openEdit(t)}
                    className={`bg-card border border-border rounded-lg p-3 cursor-grab active:cursor-grabbing hover:border-[#0F9D6E]/40 transition-colors ${dragId === t.id ? "opacity-40" : ""}`}>
                    <div className={`text-sm font-medium leading-snug ${t.status === "done" ? "line-through text-muted-foreground" : "text-foreground"}`}>{t.title}</div>
                    {t.client && <div className="text-xs text-muted-foreground mt-1">{t.client}</div>}
                    <div className="flex items-center justify-between mt-2.5">
                      <PriorityDot p={t.priority} />
                      <span className={`text-xs flex items-center gap-1 ${late ? "text-red-400" : "text-muted-foreground"}`}><Calendar size={11} />{shortDate(t.due)}</span>
                    </div>
                  </div>
                );
              })}
              {!items.length && <div className="text-xs text-muted-foreground text-center py-3 border border-dashed border-border rounded-lg">Arrastra tareas aquí</div>}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function TaskTable({ tasks, openEdit, openNew, patch, del, todayISO }: VP) {
  const [sort, setSort] = useState<{ key: "title" | "status" | "priority" | "due" | "client"; dir: 1 | -1 }>({ key: "due", dir: 1 });
  const rank = (t: Task) => ({
    title: t.title.toLowerCase(), client: t.client.toLowerCase(), due: t.due,
    status: T_STATUS.findIndex(s => s.id === t.status), priority: T_PRIORITY[t.priority].rank,
  })[sort.key];
  const rows = [...tasks].sort((a, b) => (rank(a) > rank(b) ? 1 : rank(a) < rank(b) ? -1 : 0) * sort.dir);
  const th = (key: typeof sort.key, label: string) => (
    <TH><button onClick={() => setSort(s => ({ key, dir: s.key === key ? (-s.dir as 1 | -1) : 1 }))} className="flex items-center gap-1 hover:text-foreground">
      {label}{sort.key === key && (sort.dir === 1 ? <ArrowUp size={10} /> : <ArrowDown size={10} />)}
    </button></TH>
  );
  if (!tasks.length) return <Empty onNew={() => openNew()} />;
  return (
    <Card>
      <TWrap pageSize={10}>
        <thead><tr className="border-b border-border bg-muted/30">{th("title", "Tarea")}{th("client", "Cliente")}{th("status", "Estado")}{th("priority", "Prioridad")}{th("due", "Vence")}<TH>{""}</TH></tr></thead>
        <tbody>
          {rows.map(t => {
            const late = t.status !== "done" && t.due < todayISO;
            return (
              <tr key={t.id} className="border-b border-border last:border-0 hover:bg-secondary/20 transition-colors">
                <TD><button onClick={() => openEdit(t)} className={`text-left text-sm font-medium hover:text-[#0F9D6E] ${t.status === "done" ? "line-through text-muted-foreground" : "text-foreground"}`}>{t.title}</button></TD>
                <TD><span className="text-xs text-muted-foreground">{t.client || "—"}</span></TD>
                <TD>
                  <select value={t.status} onChange={e => patch(t.id, { status: e.target.value as TStatus })} className="bg-transparent text-xs border border-border rounded-md px-1.5 py-1 focus:outline-none" style={{ color: statusOf(t.status).color }}>
                    {T_STATUS.map(s => <option key={s.id} value={s.id}>{s.label}</option>)}
                  </select>
                </TD>
                <TD>
                  <select value={t.priority} onChange={e => patch(t.id, { priority: e.target.value as TPriority })} className="bg-transparent text-xs border border-border rounded-md px-1.5 py-1 focus:outline-none" style={{ color: T_PRIORITY[t.priority].color }}>
                    {Object.entries(T_PRIORITY).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}
                  </select>
                </TD>
                <TD mono><span className={`text-xs ${late ? "text-red-400" : "text-muted-foreground"}`}>{shortDate(t.due)}</span></TD>
                <TD><button onClick={() => del(t.id)} title="Eliminar" className="p-1 rounded hover:bg-secondary transition-colors"><Trash2 size={12} className="text-muted-foreground" /></button></TD>
              </tr>
            );
          })}
        </tbody>
      </TWrap>
    </Card>
  );
}

function TaskCalendar({ tasks, openEdit, openNew, todayISO }: VP) {
  const now = new Date();
  const [cur, setCur] = useState({ y: now.getFullYear(), m: now.getMonth() });
  const label = new Date(cur.y, cur.m, 1).toLocaleDateString("es-MX", { month: "long", year: "numeric" });
  const offset = (new Date(cur.y, cur.m, 1).getDay() + 6) % 7;
  const dim = new Date(cur.y, cur.m + 1, 0).getDate();
  const cells: (number | null)[] = [...Array(offset).fill(null), ...Array.from({ length: dim }, (_, i) => i + 1)];
  while (cells.length % 7) cells.push(null);
  const move = (n: number) => setCur(c => { const d = new Date(c.y, c.m + n, 1); return { y: d.getFullYear(), m: d.getMonth() }; });
  return (
    <Card className="p-5">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <button onClick={() => move(-1)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronLeft size={14} className="text-muted-foreground" /></button>
          <button onClick={() => move(1)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronRight size={14} className="text-muted-foreground" /></button>
          <h2 className="text-base font-semibold text-foreground ml-1 first-letter:uppercase">{label}</h2>
        </div>
        <button onClick={() => setCur({ y: now.getFullYear(), m: now.getMonth() })} className="px-3 py-1.5 rounded-lg border border-border text-xs text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors">Hoy</button>
      </div>
      <div className="grid grid-cols-7 gap-px mb-1">
        {["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map(d => <div key={d} className="text-[11px] font-medium text-muted-foreground uppercase tracking-wider text-center py-1.5">{d}</div>)}
      </div>
      <div className="grid grid-cols-7 gap-1">
        {cells.map((day, i) => {
          if (day === null) return <div key={i} className="min-h-[96px] rounded-lg bg-secondary/10" />;
          const k = dKey(cur.y, cur.m, day);
          const items = tasks.filter(t => t.due === k);
          return (
            <div key={i} onClick={() => openNew({ start: k, due: k })} className="min-h-[96px] rounded-lg p-1.5 border border-border bg-secondary/20 hover:bg-secondary/40 transition-colors cursor-pointer group">
              <div className="flex items-center justify-between">
                <span className={`text-xs font-medium w-5 h-5 flex items-center justify-center rounded-full ${k === todayISO ? "bg-[#0F9D6E] text-white" : "text-foreground"}`}>{day}</span>
                <Plus size={11} className="text-muted-foreground opacity-0 group-hover:opacity-100" />
              </div>
              <div className="mt-1 space-y-1">
                {items.slice(0, 3).map(t => (
                  <button key={t.id} onClick={e => { e.stopPropagation(); openEdit(t); }}
                    className={`w-full text-left text-[10px] leading-tight px-1.5 py-1 rounded truncate ${t.status === "done" ? "line-through opacity-60" : ""}`}
                    style={{ backgroundColor: statusOf(t.status).color + "22", color: statusOf(t.status).color }}>{t.title}</button>
                ))}
                {items.length > 3 && <div className="text-[10px] text-muted-foreground px-1">+{items.length - 3} más</div>}
              </div>
            </div>
          );
        })}
      </div>
      <div className="flex flex-wrap gap-4 mt-4">
        {T_STATUS.map(s => <div key={s.id} className="flex items-center gap-1.5 text-xs text-muted-foreground"><span className="w-2 h-2 rounded-full" style={{ backgroundColor: s.color }} />{s.label}</div>)}
      </div>
    </Card>
  );
}

function TaskTimeline({ tasks, openEdit, openNew, todayISO }: VP) {
  const DAYS = 35, W = 34;
  const [weekOff, setWeekOff] = useState(0);
  const base = addDays(new Date(), weekOff * 7);
  const winStart = addDays(base, -((base.getDay() + 6) % 7) - 7);
  const days = Array.from({ length: DAYS }, (_, i) => addDays(winStart, i));
  const idx = (s: string) => Math.round((parseISO(s).getTime() - winStart.getTime()) / 86400000);
  const todayIdx = idx(todayISO);
  const rows = [...tasks].sort((a, b) => a.start.localeCompare(b.start));
  const rangeLabel = `${days[0].toLocaleDateString("es-MX", { day: "numeric", month: "short" })} – ${days[DAYS - 1].toLocaleDateString("es-MX", { day: "numeric", month: "short", year: "numeric" })}`;
  if (!tasks.length) return <Empty onNew={() => openNew()} />;
  return (
    <Card className="p-5">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <button onClick={() => setWeekOff(w => w - 2)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronLeft size={14} className="text-muted-foreground" /></button>
          <button onClick={() => setWeekOff(w => w + 2)} className="p-1.5 rounded-lg border border-border hover:bg-secondary transition-colors"><ChevronRight size={14} className="text-muted-foreground" /></button>
          <span className="text-sm font-semibold text-foreground ml-1">{rangeLabel}</span>
        </div>
        <button onClick={() => setWeekOff(0)} className="px-3 py-1.5 rounded-lg border border-border text-xs text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors">Hoy</button>
      </div>
      <div className="overflow-x-auto">
        <div style={{ width: 220 + DAYS * W }}>
          <div className="flex border-b border-border">
            <div style={{ width: 220 }} className="shrink-0 text-xs text-muted-foreground py-2 pr-3">Tarea</div>
            {days.map((d, i) => (
              <div key={i} style={{ width: W }} className={`shrink-0 text-center py-1 text-[10px] ${isoOf(d) === todayISO ? "text-[#0F9D6E] font-bold" : "text-muted-foreground"} ${d.getDay() === 1 ? "border-l border-border" : ""}`}>
                <div>{["D", "L", "M", "M", "J", "V", "S"][d.getDay()]}</div><div>{d.getDate()}</div>
              </div>
            ))}
          </div>
          <div className="relative">
            {todayIdx >= 0 && todayIdx < DAYS && <div className="absolute top-0 bottom-0 w-px bg-[#0F9D6E]/60 z-10" style={{ left: 220 + todayIdx * W + W / 2 }} />}
            {rows.map(t => {
              const s = Math.max(idx(t.start), 0), e = Math.min(idx(t.due), DAYS - 1);
              const visible = idx(t.due) >= 0 && idx(t.start) <= DAYS - 1;
              const st = statusOf(t.status);
              return (
                <div key={t.id} className="flex items-center border-b border-border last:border-0 h-11">
                  <button onClick={() => openEdit(t)} style={{ width: 220 }} className="shrink-0 text-left pr-3 truncate text-sm text-foreground hover:text-[#0F9D6E]">{t.title}</button>
                  <div className="relative h-full" style={{ width: DAYS * W }}>
                    {visible && (
                      <button onClick={() => openEdit(t)} title={`${t.title} · ${shortDate(t.start)} → ${shortDate(t.due)}`}
                        className="absolute top-1/2 -translate-y-1/2 h-6 rounded-md text-[10px] px-2 text-left truncate font-medium"
                        style={{ left: s * W + 2, width: Math.max((e - s + 1) * W - 4, 14), backgroundColor: st.color + "33", border: `1px solid ${st.color}`, color: st.color }}>
                        {(e - s + 1) >= 3 ? st.label : ""}
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
      <div className="flex flex-wrap gap-4 mt-4">
        {T_STATUS.map(s => <div key={s.id} className="flex items-center gap-1.5 text-xs text-muted-foreground"><span className="w-2 h-2 rounded-full" style={{ backgroundColor: s.color }} />{s.label}</div>)}
      </div>
    </Card>
  );
}

function CalendarModule() {
  return (
    <div>
      <div className="mb-5">
        <h1 className="text-xl font-semibold text-foreground">Calendario</h1>
        <p className="text-sm text-muted-foreground mt-0.5">Reuniones, entregas, pagos y campañas de la agencia</p>
      </div>
      <CalendarView />
    </div>
  );
}

// ─── Identidad de marca ──────────────────────────────────────────────────────

type BrandIdentity = {
  logo: string; slogan: string;
  colors: { id: number; name: string; hex: string }[];
  headingFont: string; bodyFont: string;
  tone: string[]; voice: string;
  mission: string; vision: string; values: string;
};

const BRAND_FONTS = ["DM Sans", "Inter", "Poppins", "Montserrat", "Playfair Display", "Lora", "Roboto", "Open Sans", "Raleway", "Space Grotesk"];
const TONE_OPTIONS = ["Cercana", "Profesional", "Divertida", "Elegante", "Innovadora", "Confiable", "Directa", "Inspiradora"];

const defaultIdentity = (): BrandIdentity => ({
  logo: "", slogan: "",
  colors: [
    { id: 1, name: "Primario",   hex: "#0F9D6E" },
    { id: 2, name: "Secundario", hex: "#14B8A6" },
    { id: 3, name: "Oscuro",     hex: "#0F172A" },
    { id: 4, name: "Claro",      hex: "#F6F8FA" },
  ],
  headingFont: "DM Sans", bodyFont: "Inter",
  tone: ["Cercana", "Profesional"], voice: "",
  mission: "", vision: "", values: "",
});

const readBrand = () => { try { return localStorage.getItem("agencyos-brand") || CLIENTS[0].company; } catch { return CLIENTS[0].company; } };
const identityKey = (b: string) => "agencyos-identity-" + b;

function IdentityModule() {
  const [brand, setBrand] = useState(readBrand);
  const [data, setData] = useState<BrandIdentity>(defaultIdentity);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    const on = () => setBrand(readBrand());
    window.addEventListener("agencyos-brand", on);
    return () => window.removeEventListener("agencyos-brand", on);
  }, []);

  useEffect(() => {
    try { const raw = localStorage.getItem(identityKey(brand)); setData(raw ? { ...defaultIdentity(), ...JSON.parse(raw) } : defaultIdentity()); }
    catch { setData(defaultIdentity()); }
  }, [brand]);

  useEffect(() => {
    [data.headingFont, data.bodyFont].forEach(f => {
      const id = "gf-" + f.replace(/\s+/g, "-");
      if (document.getElementById(id)) return;
      const l = document.createElement("link");
      l.id = id; l.rel = "stylesheet";
      l.href = "https://fonts.googleapis.com/css2?family=" + encodeURIComponent(f).replace(/%20/g, "+") + ":wght@400;600;700&display=swap";
      document.head.appendChild(l);
    });
  }, [data.headingFont, data.bodyFont]);

  const update = (patch: Partial<BrandIdentity>) => {
    const next = { ...data, ...patch };
    setData(next);
    try { localStorage.setItem(identityKey(brand), JSON.stringify(next)); setSaved(true); setTimeout(() => setSaved(false), 1200); } catch {}
  };

  const onLogo = (file?: File | null) => {
    if (!file) return;
    if (file.size > 1.5 * 1024 * 1024) { alert("El logo debe pesar menos de 1.5 MB."); return; }
    const r = new FileReader();
    r.onload = () => update({ logo: String(r.result) });
    r.readAsDataURL(file);
  };
  const setColor = (id: number, p: Partial<{ name: string; hex: string }>) => update({ colors: data.colors.map(c => c.id === id ? { ...c, ...p } : c) });
  const toggleTone = (t: string) => update({ tone: data.tone.includes(t) ? data.tone.filter(x => x !== t) : [...data.tone, t] });
  const copy = (txt: string) => { try { navigator.clipboard.writeText(txt); } catch {} };

  const primary = data.colors[0]?.hex || "#0F9D6E";

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-3 mb-6">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Identidad de marca</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{brand} · guía visual y de comunicación</p>
        </div>
        <span className={`flex items-center gap-1.5 text-xs transition-opacity ${saved ? "opacity-100 text-emerald-400" : "opacity-0"}`}><Check size={12} />Guardado</span>
      </div>

      <div className="grid lg:grid-cols-3 gap-4 mb-4">
        <Card className="p-5">
          <h2 className="text-sm font-semibold text-foreground mb-4">Logo</h2>
          <div className="h-36 rounded-xl border border-dashed border-border bg-secondary/20 flex items-center justify-center overflow-hidden mb-3">
            {data.logo ? <img src={data.logo} alt={"Logo de " + brand} className="max-h-full max-w-full object-contain p-3" />
              : <div className="text-center text-muted-foreground"><ImageIcon size={22} className="mx-auto mb-1.5" /><div className="text-xs">Sin logo</div></div>}
          </div>
          <div className="flex gap-2">
            <label className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg bg-[#0F9D6E] hover:bg-[#0B7C57] text-white text-sm font-medium cursor-pointer transition-colors">
              <Upload size={13} />{data.logo ? "Cambiar" : "Subir logo"}
              <input type="file" accept="image/*" className="hidden" onChange={e => { onLogo(e.target.files?.[0]); e.target.value = ""; }} />
            </label>
            {data.logo && <button onClick={() => update({ logo: "" })} title="Quitar logo" className="px-3 py-2 rounded-lg border border-border hover:bg-secondary transition-colors"><Trash2 size={13} className="text-muted-foreground" /></button>}
          </div>
          <div className="mt-4">
            <Field label="Slogan"><input value={data.slogan} onChange={e => update({ slogan: e.target.value })} className={inputCls} placeholder="La frase que define a la marca" /></Field>
          </div>
        </Card>

        <Card className="lg:col-span-2 p-5">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-semibold text-foreground">Paleta de colores</h2>
            <button onClick={() => update({ colors: [...data.colors, { id: Date.now(), name: "Nuevo color", hex: "#3B82F6" }] })}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-border text-xs text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors"><Plus size={12} />Agregar color</button>
          </div>
          <div className="grid sm:grid-cols-2 gap-3">
            {data.colors.map(c => (
              <div key={c.id} className="flex items-center gap-3 p-3 rounded-xl border border-border bg-secondary/20">
                <label className="relative w-12 h-12 rounded-lg border border-border cursor-pointer shrink-0 overflow-hidden" style={{ backgroundColor: c.hex }}>
                  <input type="color" value={c.hex} onChange={e => setColor(c.id, { hex: e.target.value })} className="absolute inset-0 opacity-0 cursor-pointer" />
                </label>
                <div className="flex-1 min-w-0 space-y-1">
                  <input value={c.name} onChange={e => setColor(c.id, { name: e.target.value })} className="w-full bg-transparent text-sm font-medium text-foreground focus:outline-none border-0 p-0 shadow-none focus:ring-0" style={{ border: "none", padding: 0, boxShadow: "none", backgroundColor: "transparent" }} />
                  <button onClick={() => copy(c.hex)} title="Copiar" className="flex items-center gap-1 text-xs font-mono text-muted-foreground hover:text-foreground uppercase">{c.hex}<Copy size={10} /></button>
                </div>
                <button onClick={() => update({ colors: data.colors.filter(x => x.id !== c.id) })} title="Eliminar" className="p-1 rounded hover:bg-secondary transition-colors"><Trash2 size={12} className="text-muted-foreground" /></button>
              </div>
            ))}
            {!data.colors.length && <p className="text-xs text-muted-foreground">Agrega los colores de la marca.</p>}
          </div>
          {data.colors.length > 0 && (
            <div className="flex h-3 rounded-full overflow-hidden mt-4 border border-border">
              {data.colors.map(c => <div key={c.id} className="flex-1" style={{ backgroundColor: c.hex }} />)}
            </div>
          )}
        </Card>
      </div>

      <div className="grid lg:grid-cols-2 gap-4 mb-4">
        <Card className="p-5">
          <h2 className="text-sm font-semibold text-foreground mb-4">Tipografía</h2>
          <div className="grid grid-cols-2 gap-3 mb-4">
            <Field label="Títulos"><select value={data.headingFont} onChange={e => update({ headingFont: e.target.value })} className={inputCls}>{BRAND_FONTS.map(f => <option key={f}>{f}</option>)}</select></Field>
            <Field label="Texto"><select value={data.bodyFont} onChange={e => update({ bodyFont: e.target.value })} className={inputCls}>{BRAND_FONTS.map(f => <option key={f}>{f}</option>)}</select></Field>
          </div>
          <div className="rounded-xl border border-border bg-secondary/20 p-5">
            <div className="text-2xl font-bold text-foreground leading-tight" style={{ fontFamily: `'${data.headingFont}', sans-serif` }}>{data.slogan || `Así se ve ${brand}`}</div>
            <p className="text-sm text-muted-foreground mt-2 leading-relaxed" style={{ fontFamily: `'${data.bodyFont}', sans-serif` }}>
              Este es un párrafo de ejemplo con la tipografía de texto. La marca comunica con claridad, consistencia y cercanía en cada punto de contacto.
            </p>
            <button className="mt-4 px-4 py-2 rounded-lg text-sm font-semibold text-white" style={{ backgroundColor: primary, fontFamily: `'${data.bodyFont}', sans-serif` }}>Llamado a la acción</button>
          </div>
        </Card>

        <Card className="p-5">
          <h2 className="text-sm font-semibold text-foreground mb-4">Voz y tono</h2>
          <div className="flex flex-wrap gap-2 mb-4">
            {TONE_OPTIONS.map(t => {
              const on = data.tone.includes(t);
              return <button key={t} onClick={() => toggleTone(t)} className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${on ? "bg-[#0F9D6E]/15 text-[#0F9D6E] border-[#0F9D6E]/40" : "text-muted-foreground border-border hover:text-foreground hover:bg-secondary/50"}`}>{t}</button>;
            })}
          </div>
          <Field label="Cómo habla la marca">
            <textarea rows={5} value={data.voice} onChange={e => update({ voice: e.target.value })} className={inputCls} placeholder="Ej. Hablamos de tú, con frases cortas, sin tecnicismos y con un toque de humor." />
          </Field>
        </Card>
      </div>

      <Card className="p-5">
        <h2 className="text-sm font-semibold text-foreground mb-4">Esencia de la marca</h2>
        <div className="grid md:grid-cols-3 gap-4">
          <Field label="Misión"><textarea rows={4} value={data.mission} onChange={e => update({ mission: e.target.value })} className={inputCls} placeholder="¿Para qué existe la marca?" /></Field>
          <Field label="Visión"><textarea rows={4} value={data.vision} onChange={e => update({ vision: e.target.value })} className={inputCls} placeholder="¿Hacia dónde va?" /></Field>
          <Field label="Valores"><textarea rows={4} value={data.values} onChange={e => update({ values: e.target.value })} className={inputCls} placeholder="Uno por línea" /></Field>
        </div>
      </Card>
    </div>
  );
}

// ─── Audiencia (buyer personas) ──────────────────────────────────────────────

type Persona = { id: number; name: string; profile: string; pains: string; message: string; channels: string };

const personasKey = (b: string) => "agencyos-personas-" + b;

function buildPersonas(a: { product: string; audience: string; pain: string; where: string }): Persona[] {
  const pains = a.pain.split(/[\n,;]+/).map(x => x.trim()).filter(Boolean);
  const p = (i: number) => pains[i] || pains[0] || a.pain;
  const now = Date.now();
  return [
    { id: now, name: "El decisor práctico", profile: `${a.audience}. Quiere resolver rápido y no tiene tiempo para comparar demasiado.`,
      pains: [p(0), "No sabe en quién confiar", "Teme perder tiempo y dinero"].join("\n"),
      message: `${a.product}: resultados claros y rápidos para que ${p(0).toLowerCase()} deje de ser un problema.`, channels: a.where },
    { id: now + 1, name: "El explorador cuidadoso", profile: `${a.audience}. Investiga mucho, compara opciones y busca pruebas antes de decidir.`,
      pains: [p(1), "Demasiada información contradictoria", "Miedo a equivocarse"].join("\n"),
      message: `Casos reales, datos y garantías: por qué ${a.product.toLowerCase()} sí funciona y cómo lo comprobamos.`, channels: a.where },
    { id: now + 2, name: "El recomendado", profile: `${a.audience}. Llega por recomendación y espera una experiencia a la altura de lo que le contaron.`,
      pains: [p(2), "Expectativas altas desde el primer contacto", "Poca paciencia con procesos largos"].join("\n"),
      message: `Te lo recomendaron por algo: ${a.product.toLowerCase()} con atención cercana y sin vueltas.`, channels: "Boca a boca, WhatsApp, reseñas · " + a.where },
  ];
}

function AudienceModule() {
  const [brand, setBrand] = useState(readBrand);
  const [personas, setPersonas] = useState<Persona[]>([]);
  const [modal, setModal] = useState<null | "quiz" | "connect" | "manual">(null);
  const [connectName, setConnectName] = useState("");
  const [step, setStep] = useState(0);
  const [ans, setAns] = useState({ product: "", audience: "", pain: "", where: "" });
  const [draft, setDraft] = useState<Persona>({ id: 0, name: "", profile: "", pains: "", message: "", channels: "" });

  useEffect(() => {
    const on = () => setBrand(readBrand());
    window.addEventListener("agencyos-brand", on);
    return () => window.removeEventListener("agencyos-brand", on);
  }, []);
  useEffect(() => {
    try { const raw = localStorage.getItem(personasKey(brand)); setPersonas(raw ? JSON.parse(raw) : []); } catch { setPersonas([]); }
  }, [brand]);
  const persist = (next: Persona[]) => { setPersonas(next); try { localStorage.setItem(personasKey(brand), JSON.stringify(next)); } catch {} };

  const QUESTIONS = [
    { key: "product" as const,  q: "¿Qué vende o hace la marca?",       hint: "Ej. Ropa deportiva para mujeres, clínica dental, software de facturación…", multi: false },
    { key: "audience" as const, q: "¿A quién le vendes?",               hint: "Edad, ocupación, ciudad, nivel de ingresos… lo que sepas.", multi: true },
    { key: "pain" as const,     q: "¿Qué problemas o dolores resuelves?", hint: "Sepáralos con comas. Ej. falta de tiempo, precios altos, mala atención.", multi: true },
    { key: "where" as const,    q: "¿Dónde los encuentras?",            hint: "Ej. Instagram, Google, referidos, ferias, WhatsApp.", multi: false },
  ];
  const cur = QUESTIONS[step];
  const startQuiz = () => { setStep(0); setAns({ product: "", audience: "", pain: "", where: "" }); setModal("quiz"); };
  const finishQuiz = () => { persist([...personas, ...buildPersonas(ans)]); setModal(null); };
  const openConnect = (name: string) => { setConnectName(name); setModal("connect"); };
  const openManual = () => { setDraft({ id: 0, name: "", profile: "", pains: "", message: "", channels: "" }); setModal("manual"); };
  const saveManual = () => {
    if (!draft.name.trim()) return;
    persist(draft.id ? personas.map(x => x.id === draft.id ? draft : x) : [...personas, { ...draft, id: Date.now() }]);
    setModal(null);
  };
  const edit = (x: Persona) => { setDraft(x); setModal("manual"); };

  const modals = (
    <>
      <Modal open={modal === "quiz"} onClose={() => setModal(null)} size="md" title="Contéstame 4 preguntas" subtitle={`Pregunta ${step + 1} de 4 · ${brand}`}
        footer={<>
          <GhostBtn onClick={() => step === 0 ? setModal(null) : setStep(step - 1)}>{step === 0 ? "Cancelar" : "Atrás"}</GhostBtn>
          <button disabled={!ans[cur.key].trim()} onClick={() => step === 3 ? finishQuiz() : setStep(step + 1)}
            className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#0F9D6E] hover:bg-[#0B7C57] disabled:opacity-40 transition-colors">{step === 3 ? "Armar buyer personas" : "Siguiente"}</button>
        </>}>
        <div className="p-6">
          <div className="h-1 rounded-full bg-secondary mb-5 overflow-hidden"><div className="h-full bg-[#0F9D6E] transition-all" style={{ width: `${((step + 1) / 4) * 100}%` }} /></div>
          <div className="text-sm font-semibold text-foreground mb-1">{cur.q}</div>
          <p className="text-xs text-muted-foreground mb-3">{cur.hint}</p>
          {cur.multi
            ? <textarea autoFocus rows={4} value={ans[cur.key]} onChange={e => setAns({ ...ans, [cur.key]: e.target.value })} className={inputCls} />
            : <input autoFocus value={ans[cur.key]} onChange={e => setAns({ ...ans, [cur.key]: e.target.value })} onKeyDown={e => { if (e.key === "Enter" && ans[cur.key].trim()) (step === 3 ? finishQuiz() : setStep(step + 1)); }} className={inputCls} />}
        </div>
      </Modal>

      <Modal open={modal === "connect"} onClose={() => setModal(null)} size="sm" title={connectName}
        footer={<><GhostBtn onClick={() => setModal(null)}>Cerrar</GhostBtn><button onClick={startQuiz} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#0F9D6E] hover:bg-[#0B7C57] transition-colors">Mejor contestar las 4 preguntas</button></>}>
        <div className="p-6 text-sm text-muted-foreground leading-relaxed">
          Esta conexión todavía no está disponible en el panel. Por ahora puedes armar las buyer personas contestando 4 preguntas o escribiéndolas tú.
        </div>
      </Modal>

      <Modal open={modal === "manual"} onClose={() => setModal(null)} size="md" title={draft.id ? "Editar buyer persona" : "Nueva buyer persona"} subtitle={brand}
        footer={<>
          {draft.id ? <button onClick={() => { persist(personas.filter(x => x.id !== draft.id)); setModal(null); }} className="mr-auto flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm text-red-400 hover:bg-red-500/10 transition-colors"><Trash2 size={13} />Eliminar</button> : null}
          <GhostBtn onClick={() => setModal(null)}>Cancelar</GhostBtn>
          <button disabled={!draft.name.trim()} onClick={saveManual} className="px-4 py-2 rounded-lg text-sm font-medium text-white bg-[#0F9D6E] hover:bg-[#0B7C57] disabled:opacity-40 transition-colors">Guardar</button>
        </>}>
        <div className="p-6 space-y-4">
          <Field label="Nombre"><input autoFocus value={draft.name} onChange={e => setDraft({ ...draft, name: e.target.value })} className={inputCls} placeholder="Ej. Laura, dueña de negocio" /></Field>
          <Field label="Perfil"><textarea rows={2} value={draft.profile} onChange={e => setDraft({ ...draft, profile: e.target.value })} className={inputCls} placeholder="Quién es, qué hace, qué busca" /></Field>
          <Field label="Dolores (uno por línea)"><textarea rows={3} value={draft.pains} onChange={e => setDraft({ ...draft, pains: e.target.value })} className={inputCls} /></Field>
          <Field label="Qué decirle"><textarea rows={2} value={draft.message} onChange={e => setDraft({ ...draft, message: e.target.value })} className={inputCls} /></Field>
          <Field label="Dónde encontrarla"><input value={draft.channels} onChange={e => setDraft({ ...draft, channels: e.target.value })} className={inputCls} /></Field>
        </div>
      </Modal>
    </>
  );

  if (!personas.length) {
    return (
      <div className="max-w-3xl mx-auto py-8 text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-secondary/60 border border-border flex items-center justify-center relative">
          <Users size={30} className="text-[#0F9D6E]" />
          <span className="absolute -top-1 -right-1 w-7 h-7 rounded-full bg-[#0F9D6E] text-white text-sm font-bold flex items-center justify-center">?</span>
        </div>
        <h1 className="text-2xl font-bold text-foreground">Cuéntame quién es tu cliente</h1>
        <p className="text-sm text-muted-foreground mt-3 max-w-md mx-auto leading-relaxed">
          Conecta una fuente y armo el perfil completo de tu audiencia, sus dolores y qué decirles. Si ya los conoces, <button onClick={openManual} className="text-[#0F9D6E] hover:underline">escríbelos tú</button>.
        </p>

        <div className="text-left mt-8">
          <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-2">Recomendado</div>
          <div className="grid sm:grid-cols-2 gap-4">
            <button onClick={() => openConnect("Conecta redes sociales")} className="text-left rounded-2xl border border-border bg-card p-5 hover:border-[#0F9D6E]/50 hover:bg-secondary/20 transition-colors flex flex-col items-start justify-start">
              <div className="w-10 h-10 rounded-xl bg-orange-500/15 flex items-center justify-center mb-4"><Link2 size={16} className="text-orange-400" /></div>
              <div className="text-sm font-semibold text-foreground">Conecta redes sociales</div>
              <p className="text-xs text-muted-foreground mt-1 leading-relaxed">Investigo a tu audiencia desde Meta, Instagram, TikTok y más.</p>
            </button>
            <button onClick={() => openConnect("Conecta Meta Ads")} className="text-left rounded-2xl border border-border bg-card p-5 hover:border-[#0F9D6E]/50 hover:bg-secondary/20 transition-colors flex flex-col items-start justify-start">
              <div className="w-10 h-10 rounded-xl bg-blue-500/15 flex items-center justify-center mb-4"><TrendingUp size={16} className="text-blue-400" /></div>
              <div className="text-sm font-semibold text-foreground">Conecta Meta Ads</div>
              <p className="text-xs text-muted-foreground mt-1 leading-relaxed">Aprendo qué creativos y ángulos están convirtiendo.</p>
            </button>
          </div>

          <div className="flex items-center gap-3 my-5">
            <span className="flex-1 h-px bg-border" />
            <span className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">O si ya lo tienes claro</span>
            <span className="flex-1 h-px bg-border" />
          </div>

          <button onClick={startQuiz} className="w-full text-left rounded-2xl border border-border bg-card p-5 flex items-center gap-4 hover:border-[#0F9D6E]/50 hover:bg-secondary/20 transition-colors">
            <div className="w-10 h-10 rounded-xl bg-[#0F9D6E]/15 flex items-center justify-center shrink-0"><MessageSquare size={16} className="text-[#0F9D6E]" /></div>
            <div>
              <div className="text-sm font-semibold text-foreground">Contéstame 4 preguntas y las armo</div>
              <p className="text-xs text-muted-foreground mt-1 leading-relaxed">Tú me cuentas a quién le vendes y yo te propongo las buyer personas en 30 segundos.</p>
            </div>
          </button>
        </div>
        {modals}
      </div>
    );
  }

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-3 mb-6">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Audiencia</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{brand} · {personas.length} buyer persona{personas.length === 1 ? "" : "s"}</p>
        </div>
        <div className="flex gap-2">
          <GhostBtn onClick={startQuiz}><MessageSquare size={14} />Armar con 4 preguntas</GhostBtn>
          <button onClick={openManual} className="flex items-center gap-2 px-4 py-2 bg-[#0F9D6E] hover:bg-[#0B7C57] text-white rounded-lg text-sm font-medium transition-colors"><Plus size={14} />Agregar</button>
        </div>
      </div>
      <div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">
        {personas.map(x => (
          <Card key={x.id} className="p-5 flex flex-col gap-3">
            <div className="flex items-start justify-between gap-2">
              <div className="flex items-center gap-3 min-w-0">
                <div className="w-9 h-9 rounded-full bg-[#0F9D6E]/20 flex items-center justify-center text-sm font-bold text-[#0F9D6E] shrink-0">{x.name.charAt(0).toUpperCase()}</div>
                <h2 className="text-sm font-semibold text-foreground leading-snug">{x.name}</h2>
              </div>
              <button onClick={() => edit(x)} title="Editar" className="p-1.5 rounded-lg hover:bg-secondary transition-colors"><Pencil size={13} className="text-muted-foreground" /></button>
            </div>
            <p className="text-xs text-muted-foreground leading-relaxed">{x.profile}</p>
            <div>
              <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Dolores</div>
              <ul className="space-y-1">{x.pains.split("\n").filter(Boolean).map((d, i) => <li key={i} className="text-xs text-foreground flex gap-2"><span className="text-red-400">•</span>{d}</li>)}</ul>
            </div>
            <div>
              <div className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-1.5">Qué decirles</div>
              <p className="text-xs text-foreground leading-relaxed">{x.message}</p>
            </div>
            <div className="mt-auto pt-3 border-t border-border text-xs text-muted-foreground"><span className="font-medium text-foreground">Dónde: </span>{x.channels}</div>
          </Card>
        ))}
      </div>
      {modals}
    </div>
  );
}

