function ServicesModule() {
  const [tab, setTab] = useState("Todos");
  const [rec, setRec] = useState<Detail | null>(null);
  const tabs = ["Todos", "SEO", "Google Ads", "Meta Ads", "Web Design", "Software"];

  const SVC_SEED = [
    { client: "FashionMX",       service: "SEO",          status: "active",      start: "2024-01-15", mrr: 18000, assigned: "Valeria Mora" },
    { client: "FashionMX",       service: "Google Ads",   status: "active",      start: "2024-01-15", mrr: 27000, assigned: "Diego Sánchez" },
    { client: "TechCorp MX",     service: "Meta Ads",     status: "active",      start: "2023-08-01", mrr: 22000, assigned: "Camila Ríos" },
    { client: "TechCorp MX",     service: "Web Design",   status: "completed",   start: "2023-08-01", mrr: 16500, assigned: "Fernanda López" },
    { client: "Clínica Lumina",  service: "SEO",          status: "active",      start: "2024-03-01", mrr: 22000, assigned: "Valeria Mora" },
    { client: "Clínica Lumina",  service: "Google Ads",   status: "active",      start: "2024-03-01", mrr: 30000, assigned: "Diego Sánchez" },
    { client: "Clínica Lumina",  service: "Meta Ads",     status: "active",      start: "2024-03-01", mrr: 20000, assigned: "Camila Ríos" },
    { client: "RestauranteCasa", service: "SEO",          status: "paused",      start: "2023-11-01", mrr: 12000, assigned: "Valeria Mora" },
    { client: "InmoBienes",      service: "SEO",          status: "active",      start: "2024-02-15", mrr: 20000, assigned: "Valeria Mora" },
    { client: "InmoBienes",      service: "Google Ads",   status: "active",      start: "2024-02-15", mrr: 38000, assigned: "Diego Sánchez" },
    { client: "LogísticaMX",     service: "Software",     status: "in_progress", start: "2024-06-01", mrr: 40000, assigned: "Fernanda López" },
    { client: "LogísticaMX",     service: "Web Design",   status: "completed",   start: "2024-06-01", mrr: 55000, assigned: "Fernanda López" },
    { client: "BellaVita Spa",   service: "Meta Ads",     status: "active",      start: "2024-04-01", mrr: 18000, assigned: "Camila Ríos" },
    { client: "BellaVita Spa",   service: "Social Media", status: "active",      start: "2024-04-01", mrr: 10000, assigned: "Camila Ríos" },
  ];

  const [svcData, setSvcData] = useState(SVC_SEED.map((r, i) => ({ ...r, id: i + 1 })));
  const [form, setForm] = useState<any | null>(null);
  const [toDelete, setToDelete] = useState<any | null>(null);
  const OWNERS = ["Valeria Mora", "Diego Sánchez", "Camila Ríos", "Fernanda López"];
  const SERVICES = ["SEO", "Google Ads", "Meta Ads", "Web Design", "Social Media", "Software"];
  const blank = { id: 0, client: CLIENTS[0].company, service: "SEO", status: "active", start: "", mrr: 0, assigned: OWNERS[0] };
  const setF = (k: string, v: any) => setForm((f: any) => ({ ...f, [k]: v }));
  const saveForm = () => {
    if (!form) return;
    setSvcData(rs => form.id ? rs.map(r => r.id === form.id ? { ...form } : r) : [...rs, { ...form, id: Math.max(0, ...rs.map(r => r.id)) + 1 }]);
    setForm(null);
  };

  const filtered = svcData.filter(s =>
    tab === "Todos" ||
    s.service === tab ||
    (tab === "Software" && s.service === "Software") ||
    (tab === "Web Design" && s.service === "Web Design")
  );

  return (
    <div>
      <div className="flex items-start justify-between mb-6">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Gestión de Servicios</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{svcData.filter(s => s.status === "active").length} servicios activos</p>
        </div>
        <PrimaryBtn onClick={() => setForm({ ...blank })}><Plus size={14} />Asignar Servicio</PrimaryBtn>
      </div>
      <SubTabs tabs={tabs} active={tab} onChange={setTab} />
      <TWrap>
        <thead>
          <tr className="bg-muted/30 border-b border-border">
            <TH>Cliente</TH><TH>Servicio</TH><TH>Estado</TH><TH>Inicio</TH><TH>Responsable</TH><TH>MRR</TH><TH> </TH>
          </tr>
        </thead>
        <tbody>
          {filtered.length === 0 && (
            <tr><td colSpan={7} className="px-4 py-12 text-center text-muted-foreground text-sm">Sin servicios en esta categoría</td></tr>
          )}
          {filtered.map((s, i) => (
            <tr key={s.id ?? i} onClick={() => setRec({
                title: s.service + " — " + s.client, kicker: "Servicio contratado",
                subtitle: "Alta " + s.start + " · responsable " + s.assigned,
                badge: <SBadge status={s.status} />,
                stats: [
                  { label: "MRR", value: money(s.mrr), color: TONE().pos },
                  { label: "Anualizado", value: money(s.mrr * 12) },
                  { label: "Meses activos", value: String(Math.max(1, Math.round((Date.parse("2024-12-31") - Date.parse(s.start)) / 2.6298e9))) },
                  { label: "Estado", value: s.status === "active" ? "Activo" : s.status === "paused" ? "Pausado" : "Cerrado" },
                ],
                fields: [
                  { label: "Cliente", value: s.client },
                  { label: "Servicio", value: s.service },
                  { label: "Inicio", value: s.start, mono: true },
                  { label: "Responsable", value: s.assigned },
                  { label: "Facturación", value: "Mensual · MXN" },
                  { label: "Ingreso acumulado", value: money(s.mrr * Math.max(1, Math.round((Date.parse("2024-12-31") - Date.parse(s.start)) / 2.6298e9))), mono: true, accent: TONE().pos },
                ],
                timeline: [
                  { date: "2024-12-05", text: "Entrega de reporte mensual al cliente", who: s.assigned },
                  { date: s.start, text: "Alta del servicio y kickoff", who: "Dirección" },
                ],
                actions: ["Ver contrato", "Editar servicio"],
              })} className="border-b border-border last:border-0 hover:bg-secondary/20 transition-colors cursor-pointer">
              <TD><div className="font-medium">{s.client}</div></TD>
              <TD>{s.service}</TD>
              <TD><SBadge status={s.status} /></TD>
              <TD><span className="text-xs text-muted-foreground">{s.start}</span></TD>
              <TD><span className="text-sm text-muted-foreground">{s.assigned}</span></TD>
              <TD mono>${s.mrr.toLocaleString("es-MX")}</TD>
              <TD>
                <div className="flex items-center gap-1 justify-end">
                  <button title="Editar servicio" onClick={e => { e.stopPropagation(); setForm({ ...s }); }}
                    className="p-1.5 hover:bg-secondary rounded-md transition-colors">
                    <Pencil size={13} className="text-muted-foreground" />
                  </button>
                  <button title="Eliminar servicio" onClick={e => { e.stopPropagation(); setToDelete(s); }}
                    className="p-1.5 hover:bg-secondary rounded-md transition-colors">
                    <Trash2 size={13} className="text-red-400" />
                  </button>
                </div>
              </TD>
            </tr>
          ))}
        </tbody>
      </TWrap>

      {form && (
        <Modal open onClose={() => setForm(null)}
          title={form.id ? "Editar servicio" : "Asignar servicio"}
          subtitle={form.id ? form.service + " — " + form.client : "Alta de servicio para un cliente"}
          footer={<>
            <GhostBtn onClick={() => setForm(null)}>Cancelar</GhostBtn>
            <PrimaryBtn onClick={saveForm}>{form.id ? "Guardar cambios" : "Asignar servicio"}</PrimaryBtn>
          </>}>
          <div className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <Field label="Cliente">
                <select className={inputCls} value={form.client} onChange={e => setF("client", e.target.value)}>
                  {CLIENTS.map(c => <option key={c.company}>{c.company}</option>)}
                </select>
              </Field>
              <Field label="Servicio">
                <select className={inputCls} value={form.service} onChange={e => setF("service", e.target.value)}>
                  {SERVICES.map(sv => <option key={sv}>{sv}</option>)}
                </select>
              </Field>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <Field label="Responsable">
                <select className={inputCls} value={form.assigned} onChange={e => setF("assigned", e.target.value)}>
                  {OWNERS.map(o => <option key={o}>{o}</option>)}
                </select>
              </Field>
              <Field label="Estado">
                <select className={inputCls} value={form.status} onChange={e => setF("status", e.target.value)}>
                  <option value="active">Activo</option>
                  <option value="paused">Pausado</option>
                  <option value="in_progress">En progreso</option>
                  <option value="completed">Completado</option>
                </select>
              </Field>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <Field label="Inicio"><input type="date" className={inputCls} value={form.start} onChange={e => setF("start", e.target.value)} /></Field>
              <Field label="MRR (MXN)"><input type="number" className={inputCls} value={form.mrr} onChange={e => setF("mrr", Number(e.target.value))} /></Field>
            </div>
          </div>
        </Modal>
      )}

      {toDelete && (
        <Modal open onClose={() => setToDelete(null)} size="md" title="Eliminar servicio"
          subtitle={toDelete.service + " — " + toDelete.client}
          footer={<>
            <GhostBtn onClick={() => setToDelete(null)}>Cancelar</GhostBtn>
            <button onClick={() => { setSvcData(rs => rs.filter(r => r.id !== toDelete.id)); setToDelete(null); }}
              className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors">
              <Trash2 size={14} />Eliminar
            </button>
          </>}>
          <div className="p-6 space-y-3">
            <p className="text-sm text-foreground leading-relaxed">
              Se dará de baja <strong>{toDelete.service}</strong> para <strong>{toDelete.client}</strong>. El histórico de facturación no se modifica.
            </p>
            <div className="rounded-lg border border-border bg-secondary/30 px-4 py-3 text-xs text-muted-foreground">
              MRR que se libera: <span className="font-mono text-foreground">{money(toDelete.mrr)}</span> · responsable {toDelete.assigned}
            </div>
          </div>
        </Modal>
      )}

      <RecordModal rec={rec} onClose={() => setRec(null)} />
    </div>
  );
}

