  const typeColor: Record<string, string> = { pdf: "#EF4444", zip: "#F59E0B", xlsx: "#10B981", png: "#0F9D6E" };
  const initials = (n: string) => n.split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase();
  const mb = (sz: string) => parseFloat(sz);

  const clientDocs = DOCS[selectedClient] || [];
  const allFiles = clientDocs.flatMap(c => c.files.map(f => ({ ...f, category: c.category })));
