type Block = { id: number; type: string; [k: string]: any };

const BLOCK_KINDS: { type: string; label: string; icon: any; make: () => Omit<Block, "id"> }[] = [
  { type: "heading", label: "Encabezado", icon: Type,
    make: () => ({ type: "heading", text: "Un título que explique el correo", align: "left" }) },
  { type: "text", label: "Párrafo", icon: FileText,
    make: () => ({ type: "text", text: "Escribe aquí el mensaje. Usa {{contacto}} y {{cliente}} para personalizar." }) },
  { type: "list", label: "Lista", icon: List,
    make: () => ({ type: "list", items: ["Primer punto", "Segundo punto", "Tercer punto"] }) },
  { type: "kpi", label: "Bloque de cifras", icon: Activity,
    make: () => ({ type: "kpi", items: [{ label: "Sesiones", value: "12,480" }, { label: "Conversiones", value: "318" }, { label: "ROAS", value: "5.4x" }] }) },
  { type: "button", label: "Botón", icon: MousePointerClick,
    make: () => ({ type: "button", text: "Ver el reporte completo", url: "https://rankpro.mx/reportes/{{cliente}}" }) },
  { type: "image", label: "Imagen", icon: ImageIcon,
    make: () => ({ type: "image", url: "", alt: "Gráfica de resultados del mes" }) },
  { type: "divider", label: "Separador", icon: Minus, make: () => ({ type: "divider" }) },
  { type: "footer", label: "Pie / firma", icon: Mail,
    make: () => ({ type: "footer", text: "RankPro · Agencia de marketing digital\nAguascalientes, México · hola@rankpro.mx" }) },
];

const EMAIL_VARS = ["{{cliente}}", "{{contacto}}", "{{servicio}}", "{{mes}}", "{{monto}}", "{{enlace_reporte}}", "{{responsable}}"];

const BRAND_COLORS = [
  { value: "#0F9D6E", label: "Verde RankPro" },
  { value: "#047857", label: "Verde profundo" },
  { value: "#1A2332", label: "Tinta" },
  { value: "#0B7A56", label: "Verde oscuro" },
  { value: "#0E1B2A", label: "Azul marino" },
];

const LOGO_OPTIONS = [
  { value: "wordmark", label: "Wordmark" },
  { value: "monogram", label: "Monograma + nombre" },
  { value: "stacked", label: "Nombre + bajada" },
  { value: "image", label: "Imagen propia" },
  { value: "none", label: "Sin logotipo" },
];

const SOCIAL_OPTIONS = [
  { key: "Instagram", url: "https://instagram.com/rankpro" },
  { key: "Facebook", url: "https://facebook.com/rankpro" },
  { key: "LinkedIn", url: "https://linkedin.com/company/rankpro" },
  { key: "WhatsApp", url: "https://wa.me/524491234567" },
  { key: "YouTube", url: "https://youtube.com/@rankpro" },
  { key: "Sitio web", url: "https://rankpro.mx" },
];

const DEFAULT_BRAND_LOGO_HW = "data:image/png;base64,";
const DEFAULT_BRAND = {
  logo: "image", logoUrl: DEFAULT_BRAND_LOGO_HW, color: "#0F9D6E",
  headerColor: "#0E1B2A",
  tagline: "Agencia de marketing digital",
  social: ["Instagram", "Facebook", "LinkedIn", "WhatsApp"],
};
const LOGO_VARIANTS = [
  { key: "horizontal-white", label: "Horizontal · blanco", url: DEFAULT_BRAND_LOGO_HW },
  { key: "vertical-white", label: "Vertical · blanco", url: "data:image/png;base64," },
  { key: "horizontal-black", label: "Horizontal · negro", url: "data:image/png;base64," },
  { key: "vertical-black", label: "Vertical · negro", url: "data:image/png;base64," },
];


const esc = (s: string) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const nl2br = (s: string) => esc(s).replace(/\n/g, "<br>");

function blockHtml(b: Block, accent = "#0F9D6E"): string {
  switch (b.type) {
    case "heading":
      return `      <tr><td class="rp-pad" style="padding:0 32px 8px;text-align:${b.align || "left"}">
        <h1 style="margin:0;font:700 24px/1.25 'Helvetica Neue',Arial,sans-serif;color:#0F172A;letter-spacing:-.02em">${esc(b.text)}</h1>
      </td></tr>`;
    case "text":
      return `      <tr><td class="rp-pad" style="padding:8px 32px 12px">
        <p style="margin:0;font:400 15px/1.65 'Helvetica Neue',Arial,sans-serif;color:#44506B">${nl2br(b.text)}</p>
      </td></tr>`;
    case "list":
      return `      <tr><td class="rp-pad" style="padding:4px 32px 12px">
        <ul style="margin:0;padding-left:20px;font:400 15px/1.7 'Helvetica Neue',Arial,sans-serif;color:#44506B">
${(b.items || []).map((i: string) => `          <li>${esc(i)}</li>`).join("\n")}
        </ul>
      </td></tr>`;
    case "kpi":
      return `      <tr><td class="rp-pad" style="padding:8px 32px 16px">
        <table class="rp-kpi" width="100%" cellpadding="0" cellspacing="0" role="presentation"><tr>
${(b.items || []).map((i: any) => `          <td style="padding:14px 10px;background:#F4F7F9;border-radius:10px;text-align:center">
            <div style="font:700 20px/1 'Helvetica Neue',Arial,sans-serif;color:${accent}">${esc(i.value)}</div>
            <div style="margin-top:5px;font:600 11px/1.3 'Helvetica Neue',Arial,sans-serif;color:#6B7280;text-transform:uppercase;letter-spacing:.06em">${esc(i.label)}</div>
          </td>
          <td width="10"></td>`).join("\n")}
        </tr></table>
      </td></tr>`;
    case "button":
      return `      <tr><td class="rp-pad" style="padding:8px 32px 20px">
        <a href="${esc(b.url)}" style="display:inline-block;padding:13px 26px;background:${accent};color:#ffffff;border-radius:10px;font:700 15px/1 'Helvetica Neue',Arial,sans-serif;text-decoration:none">${esc(b.text)}</a>
      </td></tr>`;
    case "image":
      return `      <tr><td class="rp-pad" style="padding:8px 32px 16px">
${b.url
  ? `        <img class="rp-img" src="${esc(b.url)}" alt="${esc(b.alt)}" width="536" style="display:block;width:100%;border-radius:10px">`
  : `        <div style="padding:44px 16px;background:#F4F7F9;border:1px dashed #C9D3DD;border-radius:10px;text-align:center;font:600 13px/1.4 'Helvetica Neue',Arial,sans-serif;color:#8A97A8">${esc(b.alt)}<br><span style="font-weight:400">Pega la URL de la imagen para reemplazar este espacio</span></div>`}
      </td></tr>`;
    case "divider":
      return `      <tr><td class="rp-pad" style="padding:8px 32px 16px"><div style="height:1px;background:#E5EAF0"></div></td></tr>`;
    case "footer":
      return `      <tr><td class="rp-pad" style="padding:20px 32px 28px;border-top:1px solid #E5EAF0">
        <p style="margin:0;font:400 12px/1.6 'Helvetica Neue',Arial,sans-serif;color:#8A97A8">${nl2br(b.text)}</p>
      </td></tr>`;
    default: return "";
  }
}

function brandLogoHtml(br: any): string {
  switch (br.logo) {
    case "monogram":
      return `<table cellpadding="0" cellspacing="0" role="presentation"><tr>
            <td width="30" style="width:30px;height:30px;background:#ffffff;border-radius:9px;text-align:center;font:800 15px/30px 'Helvetica Neue',Arial,sans-serif;color:${esc(br.color)}">R</td>
            <td style="padding-left:10px;font:800 17px/1 'Helvetica Neue',Arial,sans-serif;color:#ffffff;letter-spacing:-.02em">RankPro</td>
          </tr></table>`;
    case "stacked":
      return `<div style="font:800 17px/1.1 'Helvetica Neue',Arial,sans-serif;color:#ffffff;letter-spacing:-.02em">RankPro</div>
          <div style="margin-top:4px;font:500 11px/1.3 'Helvetica Neue',Arial,sans-serif;color:rgba(255,255,255,.82)">${esc(br.tagline)}</div>`;
    case "image":
      return br.logoUrl
        ? `<img src="${esc(br.logoUrl)}" alt="RankPro" height="28" style="display:block;height:28px;border:0">`
        : `<div style="padding:7px 12px;border:1px dashed rgba(255,255,255,.55);border-radius:8px;font:600 11px/1.2 'Helvetica Neue',Arial,sans-serif;color:rgba(255,255,255,.85)">Pega la URL de tu logotipo</div>`;
    case "none":
      return "";
    default:
      return `<div style="font:800 17px/1 'Helvetica Neue',Arial,sans-serif;color:#ffffff;letter-spacing:-.02em">RankPro</div>`;
  }
}

function socialHtml(br: any): string {
  const items = SOCIAL_OPTIONS.filter(s => (br.social || []).includes(s.key));
  if (!items.length) return "";
  return `      <tr><td class="rp-pad" style="padding:4px 32px 26px">
        <div>
${items.map(s => `          <a href="${s.url}" style="display:inline-block;margin:0 8px 8px 0;padding:7px 12px;background:#F4F7F9;border-radius:8px;font:600 11px/1 'Helvetica Neue',Arial,sans-serif;color:${esc(br.color)};text-decoration:none">${esc(s.key)}</a>`).join("\n")}
        </div>
      </td></tr>`;
}

function renderEmailHtml(subject: string, blocks: Block[], brand?: any): string {
  const br = { ...DEFAULT_BRAND, ...(brand || {}) };
  const logo = brandLogoHtml(br);
  return `<!DOCTYPE html>
<html lang="es">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(subject)}</title>
<style>
  .rp-card,.rp-legal{width:100%!important;max-width:600px}
  @media (max-width:480px){
    .rp-pad{padding-left:20px!important;padding-right:20px!important}
    .rp-img{width:100%!important}
    .rp-kpi td{display:block!important;width:100%!important;margin-bottom:8px}
    .rp-kpi td[width="10"]{display:none!important}
  }
</style>
</head>
<body style="margin:0;padding:24px 0;background:#EEF1F5">
  <table width="100%" cellpadding="0" cellspacing="0" role="presentation"><tr><td align="center">
    <table class="rp-card" width="600" cellpadding="0" cellspacing="0" role="presentation" style="width:100%;max-width:600px;background:#ffffff;border-radius:16px;overflow:hidden">
      <tr><td class="rp-pad" style="padding:${logo ? "22px" : "14px"} 32px;background:${esc(br.headerColor ?? br.color)}">
        <table width="100%" cellpadding="0" cellspacing="0" role="presentation"><tr>
          <td align="left" style="vertical-align:middle">${logo}</td>
          <td align="right" style="vertical-align:middle;font:600 12px/1.4 'Helvetica Neue',Arial,sans-serif;color:rgba(255,255,255,.85);white-space:nowrap">{{mes}}</td>
        </tr></table>
      </td></tr>
      <tr><td style="height:26px"></td></tr>
${blocks.map(b => blockHtml(b, br.color)).filter(Boolean).join("\n")}
${socialHtml(br)}
    </table>
    <table class="rp-legal" width="600" cellpadding="0" cellspacing="0" role="presentation" style="width:100%;max-width:600px"><tr><td class="rp-pad" style="padding:16px 32px;text-align:center;font:400 11px/1.5 'Helvetica Neue',Arial,sans-serif;color:#94A3B8">
      Recibes este correo porque {{cliente}} tiene servicios activos con RankPro. · <a href="#" style="color:#94A3B8">Cancelar suscripción</a>
    </td></tr></table>
  </td></tr></table>
</body>
</html>`;
}

