const emailStore: { templates: any[] } = { templates: TEMPLATES_SEED.map(t => ({ ...t, blocks: t.blocks.map(b => ({ ...b })) })) };

function PreviewFrame({ html, width }: { html: string; width: number }) {
  return (
    <iframe title="Vista previa del correo" srcDoc={html} sandbox=""
      className="bg-white rounded-xl border border-border shadow-2xl"
      style={{ width, height: "100%", maxWidth: "100%" }} />
  );
}

function TemplateEditor({ tpl, onSave, onClose }: { tpl: any; onSave: (t: any) => void; onClose: () => void }) {
  const [name, setName] = useState(tpl.name);
  const [category, setCategory] = useState(tpl.category);
  const [subject, setSubject] = useState(tpl.subject);
  const [blocks, setBlocks] = useState<Block[]>(tpl.blocks.map((b: Block) => ({ ...b })));
  const [brand, setBrand] = useState<any>({ ...DEFAULT_BRAND, ...(tpl.brand || {}), social: [...((tpl.brand || DEFAULT_BRAND).social || DEFAULT_BRAND.social)] });
  const [view, setView] = useState<"simple" | "code">("simple");
  const [custom, setCustom] = useState<string | null>(tpl.customHtml ?? null);
  const [device, setDevice] = useState<"desktop" | "mobile">("desktop");
  const [focus, setFocus] = useState<{ id: number; field: string } | null>(null);

  const generated = renderEmailHtml(subject, blocks, brand);
  const html = custom ?? generated;

  const upd = (id: number, patch: any) => setBlocks(bs => bs.map(b => b.id === id ? { ...b, ...patch } : b));
  const add = (kind: typeof BLOCK_KINDS[number]) =>
    setBlocks(bs => [...bs, { ...kind.make(), id: Math.max(0, ...bs.map(b => b.id)) + 1 }]);
  const move = (id: number, dir: -1 | 1) => setBlocks(bs => {
    const i = bs.findIndex(b => b.id === id); const j = i + dir;
    if (i < 0 || j < 0 || j >= bs.length) return bs;
    const c = [...bs]; [c[i], c[j]] = [c[j], c[i]]; return c;
  });
  const del = (id: number) => setBlocks(bs => bs.filter(b => b.id !== id));
  const insertVar = (v: string) => {
    if (!focus) return;
    const b = blocks.find(x => x.id === focus.id);
    if (!b) return;
    if (focus.field === "subject") return setSubject(s => s + " " + v);
    upd(focus.id, { [focus.field]: String(b[focus.field] ?? "") + " " + v });
  };

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-background" role="dialog" aria-modal="true">
      <header className="h-14 shrink-0 border-b border-border flex items-center justify-between gap-4 px-5" style={{ backgroundColor: "var(--sidebar)" }}>
        <div className="flex items-center gap-3 min-w-0">
          <div className="w-7 h-7 rounded-lg bg-[#0F9D6E]/15 flex items-center justify-center shrink-0"><LayoutTemplate size={14} className="text-[#0F9D6E]" /></div>
          <div className="min-w-0">
            <div className="text-sm font-semibold text-foreground truncate">{name || "Plantilla sin nombre"}</div>
            <div className="text-xs text-muted-foreground">Editor en vivo · {blocks.length} bloques{custom ? " · HTML editado a mano" : ""}</div>
          </div>
        </div>
        <div className="flex items-center gap-2 shrink-0">
          <div className="flex rounded-lg border border-border overflow-hidden">
            <button onClick={() => setView("simple")}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium transition-colors ${view === "simple" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}>
              <LayoutTemplate size={12} />Vista sencilla
            </button>
            <button onClick={() => setView("code")}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium transition-colors ${view === "code" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}>
              <Code size={12} />Vista avanzada
            </button>
          </div>
          <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
          <PrimaryBtn onClick={() => onSave({ ...tpl, name, category, subject, blocks, brand, customHtml: custom, updated: "2024-12-12" })}>
            <Save size={14} />Guardar plantilla
          </PrimaryBtn>
        </div>
      </header>

      <div className="flex-1 min-h-0 flex">
        <div className="w-[430px] shrink-0 border-r border-border overflow-y-auto">
          <div className="p-5 space-y-4 border-b border-border">
            <div className="grid grid-cols-2 gap-3">
              <Field label="Nombre de la plantilla">
                <input className={inputCls} value={name} onChange={e => setName(e.target.value)} />
              </Field>
              <Field label="Categoría">
                <select className={inputCls} value={category} onChange={e => setCategory(e.target.value)}>
                  {["Reportes", "Comercial", "Cobranza", "Transaccional"].map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </Field>
            </div>
            <Field label="Asunto del correo">
              <input className={inputCls} value={subject} onChange={e => setSubject(e.target.value)}
                onFocus={() => setFocus({ id: -1, field: "subject" })} />
            </Field>
            <div>
              <div className="text-xs text-muted-foreground mb-1.5">Variables · clic para insertarlas en el campo activo</div>
              <div className="flex flex-wrap gap-1.5">
                {EMAIL_VARS.map(v => (
                  <button key={v} onClick={() => insertVar(v)} disabled={!focus}
                    className="font-mono text-xs px-2 py-1 rounded-md border border-border text-muted-foreground hover:text-[#0F9D6E] hover:border-[#0F9D6E]/40 transition-colors disabled:opacity-40">
                    {v}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {view === "simple" ? (
            <div className="p-5 space-y-3">
              {custom && (
                <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 p-3">
                  <div className="text-xs text-amber-400 font-medium mb-1.5">Este correo tiene HTML editado a mano</div>
                  <p className="text-xs text-muted-foreground mb-2">Los bloques dejaron de controlar la vista previa. Puedes seguir editando el código o volver a los bloques descartando los cambios manuales.</p>
                  <button onClick={() => setCustom(null)} className="text-xs font-medium text-[#0F9D6E] hover:underline">Volver a los bloques</button>
                </div>
              )}
              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Marca del correo</div>
              <div className="rounded-xl border border-border bg-card p-3 space-y-3">
                <Field label="Logotipo en la cabecera">
                  <select className={inputCls} value={brand.logo} onChange={e => setBrand({ ...brand, logo: e.target.value })}>
                    {LOGO_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                  </select>
                </Field>
                {brand.logo === "image" && (
                  <Field label="URL del logotipo (PNG o SVG, alto 28px)">
                    <input className={inputCls + " font-mono text-xs"} placeholder="https://rankpro.mx/logo.png"
                      value={brand.logoUrl} onChange={e => setBrand({ ...brand, logoUrl: e.target.value })} />
                  </Field>
                )}
                {brand.logo === "image" && (
                  <div>
                    <div className="text-xs text-muted-foreground mb-1.5">Variante del logotipo</div>
                    <div className="grid grid-cols-4 gap-2 mb-2">
                      {LOGO_VARIANTS.map(v => (
                        <button key={v.key} type="button" onClick={() => setBrand({ ...brand, logoUrl: v.url })} title={v.label}
                          className={`rounded-lg border p-2 flex items-center justify-center h-14 transition-colors ${brand.logoUrl === v.url ? "border-[#0F9D6E] bg-[#0F9D6E]/10" : "border-border hover:bg-secondary"}`}
                          style={{ background: v.key.endsWith("white") ? "#0F9D6E" : "#ffffff" }}>
                          <img src={v.url} alt={v.label} className="max-h-8 max-w-full object-contain" />
                        </button>
                      ))}
                    </div>
                  </div>
                )}
                {brand.logo === "stacked" && (
                  <Field label="Bajada bajo el nombre">
                    <input className={inputCls} value={brand.tagline} onChange={e => setBrand({ ...brand, tagline: e.target.value })} />
                  </Field>
                )}

                <div>
                  <div className="text-xs text-muted-foreground mb-1.5">Color de marca · cabecera, botones y cifras</div>
                  <div className="flex flex-wrap gap-2">
                    {BRAND_COLORS.map(c => (
                      <button key={c.value} onClick={() => setBrand({ ...brand, color: c.value })} title={c.label}
                        className={`flex items-center gap-2 pl-1.5 pr-2.5 py-1.5 rounded-lg border text-xs font-medium transition-colors ${brand.color === c.value ? "border-[#0F9D6E] text-foreground bg-secondary/50" : "border-border text-muted-foreground hover:text-foreground"}`}>
                        <span className="w-4 h-4 rounded-md shrink-0 flex items-center justify-center" style={{ backgroundColor: c.value }}>
                          {brand.color === c.value && <Check size={10} className="text-white" />}
                        </span>
                        {c.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <div className="text-xs text-muted-foreground mb-1.5">Redes sociales en el pie · {brand.social.length} activas</div>
                  <div className="flex flex-wrap gap-1.5">
                    {SOCIAL_OPTIONS.map(s => {
                      const on = brand.social.includes(s.key);
                      return (
                        <button key={s.key} title={s.url}
                          onClick={() => setBrand({ ...brand, social: on ? brand.social.filter((x: string) => x !== s.key) : [...brand.social, s.key] })}
                          className={`px-2.5 py-1 rounded-md border text-xs font-medium transition-colors ${on ? "border-[#0F9D6E]/40 bg-[#0F9D6E]/10 text-[#0F9D6E]" : "border-border text-muted-foreground hover:text-foreground"}`}>
                          {s.key}
                        </button>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Bloques del correo</div>
              {blocks.map((b, i) => {
                const kind = BLOCK_KINDS.find(k => k.type === b.type);
                const Icon = kind?.icon ?? FileText;
                return (
                  <div key={b.id} className="rounded-xl border border-border bg-card">
                    <div className="flex items-center justify-between gap-2 px-3 py-2 border-b border-border">
                      <div className="flex items-center gap-2 min-w-0">
                        <Icon size={13} className="text-[#0F9D6E] shrink-0" />
                        <span className="text-xs font-medium text-foreground truncate">{kind?.label ?? b.type}</span>
                        <span className="text-xs text-muted-foreground font-mono shrink-0">#{i + 1}</span>
                      </div>
                      <div className="flex items-center gap-0.5 shrink-0">
                        <button onClick={() => move(b.id, -1)} disabled={i === 0} title="Subir"
                          className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary disabled:opacity-30"><ArrowUp size={12} /></button>
                        <button onClick={() => move(b.id, 1)} disabled={i === blocks.length - 1} title="Bajar"
                          className="p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary disabled:opacity-30"><ArrowDown size={12} /></button>
                        <button onClick={() => del(b.id)} title="Eliminar bloque"
                          className="p-1 rounded-md text-muted-foreground hover:text-red-400 hover:bg-secondary"><Trash2 size={12} /></button>
                      </div>
                    </div>
                    <div className="p-3 space-y-2.5">
                      {b.type === "heading" && (<>
                        <input className={inputCls} value={b.text} onFocus={() => setFocus({ id: b.id, field: "text" })}
                          onChange={e => upd(b.id, { text: e.target.value })} />
                        <div className="flex gap-1.5">
                          {["left", "center"].map(a => (
                            <button key={a} onClick={() => upd(b.id, { align: a })}
                              className={`px-2.5 py-1 rounded-md text-xs border transition-colors ${b.align === a ? "border-[#0F9D6E] text-[#0F9D6E] bg-[#0F9D6E]/10" : "border-border text-muted-foreground hover:text-foreground"}`}>
                              {a === "left" ? "Izquierda" : "Centrado"}
                            </button>
                          ))}
                        </div>
                      </>)}
                      {b.type === "text" && (
                        <textarea rows={4} className={inputCls + " resize-y"} value={b.text}
                          onFocus={() => setFocus({ id: b.id, field: "text" })}
                          onChange={e => upd(b.id, { text: e.target.value })} />
                      )}
                      {b.type === "footer" && (
                        <textarea rows={3} className={inputCls + " resize-y"} value={b.text}
                          onFocus={() => setFocus({ id: b.id, field: "text" })}
                          onChange={e => upd(b.id, { text: e.target.value })} />
                      )}
                      {b.type === "list" && (<>
                        {(b.items as string[]).map((it, k) => (
                          <div key={k} className="flex items-center gap-1.5">
                            <input className={inputCls} value={it}
                              onChange={e => upd(b.id, { items: (b.items as string[]).map((x, n) => n === k ? e.target.value : x) })} />
                            <button onClick={() => upd(b.id, { items: (b.items as string[]).filter((_, n) => n !== k) })}
                              className="p-1.5 rounded-md text-muted-foreground hover:text-red-400 hover:bg-secondary shrink-0"><X size={12} /></button>
                          </div>
                        ))}
                        <button onClick={() => upd(b.id, { items: [...(b.items as string[]), "Nuevo punto"] })}
                          className="text-xs font-medium text-[#0F9D6E] hover:underline">+ Añadir punto</button>
                      </>)}
                      {b.type === "kpi" && (<>
                        {(b.items as any[]).map((it, k) => (
                          <div key={k} className="flex items-center gap-1.5">
                            <input className={inputCls} placeholder="Etiqueta" value={it.label}
                              onChange={e => upd(b.id, { items: (b.items as any[]).map((x, n) => n === k ? { ...x, label: e.target.value } : x) })} />
                            <input className={inputCls + " font-mono"} placeholder="Valor" value={it.value}
                              onChange={e => upd(b.id, { items: (b.items as any[]).map((x, n) => n === k ? { ...x, value: e.target.value } : x) })} />
                            <button onClick={() => upd(b.id, { items: (b.items as any[]).filter((_, n) => n !== k) })}
                              className="p-1.5 rounded-md text-muted-foreground hover:text-red-400 hover:bg-secondary shrink-0"><X size={12} /></button>
                          </div>
                        ))}
                        {(b.items as any[]).length < 4 && (
                          <button onClick={() => upd(b.id, { items: [...(b.items as any[]), { label: "Métrica", value: "0" }] })}
                            className="text-xs font-medium text-[#0F9D6E] hover:underline">+ Añadir cifra</button>
                        )}
                      </>)}
                      {b.type === "button" && (<>
                        <Field label="Texto del botón">
                          <input className={inputCls} value={b.text} onChange={e => upd(b.id, { text: e.target.value })} />
                        </Field>
                        <Field label="Enlace">
                          <input className={inputCls + " font-mono text-xs"} value={b.url}
                            onFocus={() => setFocus({ id: b.id, field: "url" })}
                            onChange={e => upd(b.id, { url: e.target.value })} />
                        </Field>
                      </>)}
                      {b.type === "image" && (<>
                        <Field label="URL de la imagen">
                          <input className={inputCls + " font-mono text-xs"} placeholder="https://…" value={b.url}
                            onChange={e => upd(b.id, { url: e.target.value })} />
                        </Field>
                        <Field label="Texto alternativo">
                          <input className={inputCls} value={b.alt} onChange={e => upd(b.id, { alt: e.target.value })} />
                        </Field>
                      </>)}
                      {b.type === "divider" && <p className="text-xs text-muted-foreground">Línea divisoria de 1px, sin opciones.</p>}
                    </div>
                  </div>
                );
              })}

              <div className="pt-2">
                <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2">Añadir bloque</div>
                <div className="grid grid-cols-2 gap-2">
                  {BLOCK_KINDS.map(k => (
                    <button key={k.type} onClick={() => add(k)}
                      className="flex items-center gap-2 px-3 py-2 rounded-lg border border-border text-xs font-medium text-muted-foreground hover:text-foreground hover:border-[#0F9D6E]/40 hover:bg-secondary/40 transition-colors">
                      <k.icon size={13} className="text-[#0F9D6E]" />{k.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="p-5 space-y-3">
              <div className="flex items-center justify-between gap-3">
                <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">HTML del correo</div>
                {custom && (
                  <button onClick={() => setCustom(null)} className="text-xs font-medium text-[#0F9D6E] hover:underline">Regenerar desde bloques</button>
                )}
              </div>
              <p className="text-xs text-muted-foreground">
                Edita el código y la vista previa se actualiza al momento. En cuanto toques el HTML, los bloques dejan de sobrescribirlo.
              </p>
              <textarea
                value={html}
                onChange={e => setCustom(e.target.value)}
                spellCheck={false}
                className="w-full h-[calc(100vh-380px)] min-h-[320px] px-3 py-3 bg-secondary/40 border border-border rounded-lg text-xs leading-relaxed text-foreground font-mono focus:outline-none focus:border-[#0F9D6E] transition-colors resize-none"
              />
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <span className="font-mono">{html.length.toLocaleString("es-MX")} caracteres</span>
                <span>·</span>
                <span>{custom ? "HTML manual" : "generado desde bloques"}</span>
              </div>
            </div>
          )}
        </div>

        <div className="flex-1 min-w-0 flex flex-col bg-muted/30">
          <div className="h-11 shrink-0 border-b border-border flex items-center justify-between px-4">
            <div className="flex items-center gap-2 min-w-0">
              <Eye size={13} className="text-muted-foreground shrink-0" />
              <span className="text-xs text-muted-foreground truncate">Asunto: <span className="text-foreground">{subject || "(sin asunto)"}</span></span>
            </div>
            <div className="flex rounded-lg border border-border overflow-hidden shrink-0">
              <button onClick={() => setDevice("desktop")} title="Escritorio"
                className={`px-2.5 py-1.5 transition-colors ${device === "desktop" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}><Monitor size={12} /></button>
              <button onClick={() => setDevice("mobile")} title="Móvil"
                className={`px-2.5 py-1.5 transition-colors ${device === "mobile" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}><Smartphone size={12} /></button>
            </div>
          </div>
          <div className="flex-1 min-h-0 overflow-auto p-6 flex justify-center">
            <PreviewFrame html={html} width={device === "desktop" ? 660 : 390} />
          </div>
        </div>
      </div>
    </div>
  );
}

function TemplatesModule() {
  const [tpls, setTpls] = useState<any[]>(emailStore.templates.map(t => ({ ...t, blocks: t.blocks.map((b: Block) => ({ ...b })) })));
  const [q, setQ] = useState("");
  const [cat, setCat] = useState("Todas");
  const [editing, setEditing] = useState<any | null>(null);
  const [rec, setRec] = useState<Detail | null>(null);

  const commit = (next: any[]) => { setTpls(next); emailStore.templates = next; };
  const cats = ["Todas", "Reportes", "Comercial", "Cobranza", "Transaccional"];
  const rows = tpls.filter(t =>
    (cat === "Todas" || t.category === cat) &&
    (t.name + t.subject + t.category).toLowerCase().includes(q.toLowerCase()));

  const blank = {
    id: 0, name: "", category: "Reportes", status: "active", subject: "", updated: "2024-12-12",
    uses: 0, openRate: 0, author: "Ana Martínez",
    blocks: tplBlocks(
      { type: "heading", text: "Un título que explique el correo", align: "left" },
      { type: "text", text: "Hola {{contacto}}, escribe aquí el mensaje." },
      { type: "footer", text: "RankPro · hola@rankpro.mx" },
    ),
  };

  const save = (t: any) => {
    commit(t.id ? tpls.map(x => x.id === t.id ? t : x)
                : [...tpls, { ...t, id: Math.max(0, ...tpls.map(x => x.id)) + 1 }]);
    setEditing(null);
  };

  const detailOf = (t: any): Detail => ({
    title: t.name, kicker: t.category,
    subtitle: `Asunto: ${t.subject}`,
    badge: <SBadge status={t.status} />,
    stats: [
      { label: "Bloques", value: String(t.blocks.length) },
      { label: "Envíos", value: String(t.uses) },
      { label: "Apertura", value: t.openRate + "%", color: t.openRate >= 55 ? TONE().pos : TONE().warn },
      { label: "HTML", value: t.customHtml ? "Manual" : "Bloques" },
    ],
    fields: [
      { label: "Categoría", value: t.category },
      { label: "Autor", value: t.author },
      { label: "Última edición", value: t.updated, mono: true },
      { label: "Peso del HTML", value: (renderEmailHtml(t.subject, t.blocks, t.brand).length / 1024).toFixed(1) + " KB", mono: true },
      { label: "Logotipo", value: LOGO_OPTIONS.find(o => o.value === (t.brand?.logo ?? DEFAULT_BRAND.logo))?.label ?? "Wordmark" },
      { label: "Color de marca", value: BRAND_COLORS.find(c => c.value === (t.brand?.color ?? DEFAULT_BRAND.color))?.label ?? (t.brand?.color ?? DEFAULT_BRAND.color), accent: t.brand?.color ?? DEFAULT_BRAND.color },
    ],
    tags: [
      { label: "Bloques en orden", items: t.blocks.map((b: Block) => BLOCK_KINDS.find(k => k.type === b.type)?.label ?? b.type) },
      { label: "Variables usadas", items: EMAIL_VARS.filter(v => JSON.stringify(t.blocks).includes(v) || t.subject.includes(v)) },
      { label: "Redes en el pie", items: (t.brand?.social ?? DEFAULT_BRAND.social) },
    ],
    timeline: [
      { date: t.updated, text: "Última edición de la plantilla", who: t.author },
      { date: "2024-11-02", text: `Plantilla usada en ${t.uses} envíos acumulados`, who: "Sistema" },
    ],
    actions: ["Duplicar", "Abrir el editor"],
  });

  const kpis = {
    total: tpls.length,
    active: tpls.filter(t => t.status === "active").length,
    uses: tpls.reduce((s, t) => s + t.uses, 0),
    open: tpls.length ? (tpls.reduce((s, t) => s + t.openRate * t.uses, 0) / Math.max(1, tpls.reduce((s, t) => s + t.uses, 0))).toFixed(1) : "0",
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Plantillas de Correo</h1>
          <p className="text-sm text-muted-foreground mt-0.5">{tpls.length} plantillas · editor en vivo con vista sencilla por bloques y vista avanzada en HTML</p>
        </div>
        <PrimaryBtn onClick={() => setEditing(blank)}><Plus size={14} />Nueva plantilla</PrimaryBtn>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        <Kpi label="Plantillas" value={String(kpis.total)} sub={kpis.active + " activas"} icon={LayoutTemplate} color="#0F9D6E" />
        <Kpi label="Envíos con plantilla" value={kpis.uses.toLocaleString("es-MX")} sub="acumulado histórico" icon={Send} color="#3B82F6" />
        <Kpi label="Apertura ponderada" value={kpis.open + "%"} sub="por volumen de envío" icon={Eye} color="#8B5CF6" />
        <Kpi label="En pausa" value={String(tpls.filter(t => t.status !== "active").length)} sub="no disponibles para envío" icon={Clock} color="#F59E0B" />
      </div>

      <Card className="p-4">
        <div className="flex flex-wrap items-center gap-3">
          <div className="relative flex-1 min-w-[220px]">
            <Search size={13} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
            <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar por nombre, asunto o categoría…"
              className={inputCls + " pl-8"} />
          </div>
          <div className="flex flex-wrap gap-1.5">
            {cats.map(c => (
              <button key={c} onClick={() => setCat(c)}
                className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${cat === c ? "bg-[#0F9D6E] text-white border-[#0F9D6E]" : "border-border text-muted-foreground hover:text-foreground hover:bg-secondary"}`}>
                {c}
              </button>
            ))}
          </div>
        </div>
      </Card>

      <TWrap>
        <thead>
          <tr>
            <TH>Plantilla</TH><TH>Asunto</TH><TH>Bloques</TH><TH>Envíos</TH>
            <TH>Apertura</TH><TH>Actualizada</TH><TH>Estado</TH><TH>Acciones</TH>
          </tr>
        </thead>
        <tbody>
          {rows.map(t => (
            <tr key={t.id} className="border-b border-border last:border-0 hover:bg-secondary/20 transition-colors">
              <TD>
                <div className="flex items-center gap-2.5">
                  <div className="w-7 h-7 rounded-lg bg-[#0F9D6E]/15 flex items-center justify-center shrink-0">
                    <LayoutTemplate size={13} className="text-[#0F9D6E]" />
                  </div>
                  <div className="min-w-0">
                    <div className="font-medium text-foreground truncate">{t.name}</div>
                    <div className="text-xs text-muted-foreground">{t.category} · {t.author}</div>
                  </div>
                </div>
              </TD>
              <TD><span className="text-muted-foreground text-xs font-mono">{t.subject}</span></TD>
              <TD mono>{t.blocks.length}</TD>
              <TD mono>{t.uses}</TD>
              <TD mono><span style={{ color: t.openRate >= 55 ? TONE().pos : TONE().warn }}>{t.openRate}%</span></TD>
              <TD mono>{t.updated}</TD>
              <TD><SBadge status={t.status} /></TD>
              <TD>
                <div className="flex items-center gap-0.5">
                  <button onClick={() => setRec(detailOf(t))} title="Ver ficha"
                    className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors"><Eye size={13} /></button>
                  <button onClick={() => setEditing(t)} title="Abrir el editor"
                    className="p-1.5 rounded-md text-muted-foreground hover:text-[#0F9D6E] hover:bg-secondary transition-colors"><Pencil size={13} /></button>
                  <button onClick={() => commit([...tpls, { ...t, id: Math.max(0, ...tpls.map(x => x.id)) + 1, name: t.name + " (copia)", uses: 0, openRate: 0 }])}
                    title="Duplicar" className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors"><Copy size={13} /></button>
                  <button onClick={() => commit(tpls.filter(x => x.id !== t.id))} title="Eliminar"
                    className="p-1.5 rounded-md text-muted-foreground hover:text-red-400 hover:bg-secondary transition-colors"><Trash2 size={13} /></button>
                </div>
              </TD>
            </tr>
          ))}
        </tbody>
      </TWrap>

      {editing && <TemplateEditor tpl={editing} onSave={save} onClose={() => setEditing(null)} />}
      <RecordModal rec={rec} onClose={() => setRec(null)} />
    </div>
  );
}

