function SendModule() {
  const tpls = emailStore.templates;
  const [sends, setSends] = useState<any[]>(SENDS_SEED.map(s => ({ ...s, to: [...s.to] })));
  const [tab, setTab] = useState("Nuevo envío");
  const [rec, setRec] = useState<Detail | null>(null);
  const [toast, setToast] = useState<string | null>(null);

  const firstActive = tpls.find(t => t.status === "active") ?? tpls[0];
  const [tplId, setTplId] = useState<number>(firstActive?.id ?? 0);
  const [from, setFrom] = useState("reportes@rankpro.mx");
  const [subject, setSubject] = useState(firstActive?.subject ?? "");
  const [to, setTo] = useState<string[]>([CONTACTS[0]?.email].filter(Boolean) as string[]);
  const [manual, setManual] = useState("");
  const [picker, setPicker] = useState(false);
  const [mode, setMode] = useState<"now" | "later">("now");
  const [date, setDate] = useState("2025-01-03");
  const [time, setTime] = useState("09:00");
  const [device, setDevice] = useState<"desktop" | "mobile">("desktop");
  const [attachments, setAttachments] = useState<{ name: string; size: string }[]>([]);

  const addAttachments = (files: FileList | null) => {
    if (!files) return;
    const pdfs = Array.from(files).filter(f => f.type === "application/pdf" || f.name.toLowerCase().endsWith(".pdf"));
    if (!pdfs.length) return setToast("Solo se pueden adjuntar archivos PDF.");
    setAttachments(l => [...l, ...pdfs.map(f => ({ name: f.name, size: f.size > 1024 * 1024 ? (f.size / (1024 * 1024)).toFixed(1) + " MB" : Math.max(1, Math.round(f.size / 1024)) + " KB" }))]);
  };

  const tpl = tpls.find(t => t.id === tplId) ?? firstActive;
  const html = tpl ? (tpl.customHtml ?? renderEmailHtml(subject, tpl.blocks, tpl.brand)) : "";

  const pickTpl = (id: number) => {
    setTplId(id);
    const t = tpls.find(x => x.id === id);
    if (t) setSubject(t.subject);
  };
  const addTo = (email: string) => setTo(l => l.includes(email) ? l : [...l, email]);
  const addManual = () => {
    const v = manual.trim();
    if (!v || !v.includes("@")) return;
    addTo(v); setManual("");
  };

  const submit = (status: "sent" | "scheduled" | "draft") => {
    if (!to.length && status !== "draft") return setToast("Agrega al menos un destinatario antes de enviar.");
    const when = status === "sent" ? "2024-12-12 12:40" : status === "scheduled" ? `${date} ${time}` : "—";
    setSends(l => [{
      id: Math.max(0, ...l.map(s => s.id)) + 1, subject, template: tpl?.name ?? "—", from,
      to: [...to], status, when, opens: 0, clicks: 0, owner: "Ana Martínez", attachments: [...attachments],
    }, ...l]);
    setToast(status === "sent" ? `Correo enviado a ${to.length} ${to.length === 1 ? "destinatario" : "destinatarios"}.`
      : status === "scheduled" ? `Envío programado para el ${date} a las ${time} · ${to.length} destinatarios.`
      : "Borrador guardado.");
    setAttachments([]);
    setTab("Historial y programados");
  };

  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 4500); return () => clearTimeout(t); }, [toast]);

  const detailOf = (s: any): Detail => ({
    title: s.subject, kicker: s.template,
    subtitle: `De ${s.from} · responsable ${s.owner}`,
    badge: <SBadge status={s.status} />,
    stats: [
      { label: "Destinatarios", value: String(s.to.length) },
      { label: "Aperturas", value: String(Math.min(s.opens, s.to.length)) },
      { label: "Clics", value: String(s.clicks) },
      { label: "Apertura", value: s.to.length ? Math.round((Math.min(s.opens, s.to.length) / s.to.length) * 100) + "%" : "—",
        color: s.opens ? TONE().pos : undefined },
    ],
    fields: [
      { label: "Estado", value: BADGE_MAP[s.status]?.[0] ?? s.status },
      { label: s.status === "scheduled" ? "Programado para" : "Fecha de envío", value: s.when, mono: true },
      { label: "Remitente", value: s.from, mono: true },
      { label: "Plantilla", value: s.template },
      { label: "Adjuntos", value: (s.attachments?.length ?? 0) ? `${s.attachments.length} PDF` : "Sin adjuntos" },
    ],
    tags: [{ label: "Lista de destinatarios", items: s.to },
      ...((s.attachments?.length ?? 0) ? [{ label: "PDF adjuntos", items: s.attachments.map((a: any) => a.name) }] : [])],
    timeline: [
      { date: s.when.split(" ")[0], text: s.status === "scheduled" ? "Envío en cola, aún se puede cancelar" : s.status === "failed" ? "El servidor rechazó el envío" : "Envío entregado", who: s.owner },
      { date: "2024-12-01", text: "Envío creado desde el panel", who: s.owner },
    ],
    actions: ["Duplicar", s.status === "scheduled" ? "Cancelar programación" : "Reenviar"],
  });

  const sentThisMonth = sends.filter(s => s.status === "sent").reduce((n, s) => n + s.to.length, 0);
  const scheduled = sends.filter(s => s.status === "scheduled").length;
  const opens = sends.reduce((n, s) => n + Math.min(s.opens, s.to.length), 0);
  const recipients = sends.filter(s => s.status === "sent").reduce((n, s) => n + s.to.length, 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold text-foreground">Enviar Correo</h1>
          <p className="text-sm text-muted-foreground mt-0.5">Envía ahora o programa · un correo puede ir a varias personas a la vez</p>
        </div>
        <GhostBtn onClick={() => setTab(tab === "Nuevo envío" ? "Historial y programados" : "Nuevo envío")}>
          {tab === "Nuevo envío" ? <><Inbox size={14} />Ver historial</> : <><Plus size={14} />Nuevo envío</>}
        </GhostBtn>
      </div>

      {toast && (
        <div className="flex items-center gap-2.5 rounded-xl border border-[#0F9D6E]/30 bg-[#0F9D6E]/10 px-4 py-3">
          <CheckCircle size={15} className="text-[#0F9D6E] shrink-0" />
          <span className="text-sm text-foreground">{toast}</span>
          <button onClick={() => setToast(null)} className="ml-auto p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary"><X size={12} /></button>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        <Kpi label="Correos entregados" value={sentThisMonth.toLocaleString("es-MX")} sub="suma de destinatarios" icon={Send} color="#0F9D6E" />
        <Kpi label="Programados" value={String(scheduled)} sub="en cola, cancelables" icon={CalendarClock} color="#3B82F6" />
        <Kpi label="Aperturas" value={String(opens)} sub={recipients ? Math.round((opens / recipients) * 100) + "% del total entregado" : "—"} icon={Eye} color="#8B5CF6" />
        <Kpi label="Fallidos" value={String(sends.filter(s => s.status === "failed").length)} sub="requieren revisión" icon={AlertTriangle} color="#EF4444" />
      </div>

      <SubTabs tabs={["Nuevo envío", "Historial y programados"]} active={tab} onChange={setTab} />

      {tab === "Nuevo envío" ? (
        <div className="grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_minmax(0,1fr)] gap-5">
          <Card className="p-5 space-y-4">
            <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Redactar el envío</div>

            <div className="grid grid-cols-2 gap-3">
              <Field label="Remitente">
                <select className={inputCls} value={from} onChange={e => setFrom(e.target.value)}>
                  {["reportes@rankpro.mx", "comercial@rankpro.mx", "pagos@rankpro.mx", "soporte@rankpro.mx", "hola@rankpro.mx"].map(f => <option key={f} value={f}>{f}</option>)}
                </select>
              </Field>
              <Field label="Plantilla">
                <select className={inputCls} value={tplId} onChange={e => pickTpl(Number(e.target.value))}>
                  {tpls.map(t => <option key={t.id} value={t.id} disabled={t.status !== "active"}>
                    {t.name}{t.status !== "active" ? " (en pausa)" : ""}
                  </option>)}
                </select>
              </Field>
            </div>

            <Field label="Asunto">
              <input className={inputCls} value={subject} onChange={e => setSubject(e.target.value)} />
            </Field>

            <div>
              <div className="flex items-center justify-between mb-1.5">
                <span className="text-xs text-muted-foreground">Destinatarios · {to.length} seleccionados</span>
                <div className="flex items-center gap-2">
                  <button onClick={() => setTo(CONTACTS.filter(c => c.status === "active").map(c => c.email))}
                    className="text-xs font-medium text-[#0F9D6E] hover:underline">Todos los clientes activos</button>
                  {to.length > 0 && (
                    <button onClick={() => setTo([])} className="text-xs text-muted-foreground hover:text-foreground">Limpiar</button>
                  )}
                </div>
              </div>
              <div className="rounded-lg border border-border bg-secondary/40 p-2 min-h-[44px] flex flex-wrap gap-1.5">
                {to.length === 0 && <span className="text-xs text-muted-foreground px-1 py-1">Sin destinatarios todavía</span>}
                {to.map(e => {
                  const c = CONTACTS.find(x => x.email === e);
                  return (
                    <span key={e} className="inline-flex items-center gap-1.5 pl-2 pr-1 py-1 rounded-md bg-[#0F9D6E]/15 border border-[#0F9D6E]/25 text-xs text-foreground">
                      <AtSign size={10} className="text-[#0F9D6E]" />
                      <span className="font-mono">{e}</span>
                      {c && <span className="text-muted-foreground">· {c.company}</span>}
                      <button onClick={() => setTo(l => l.filter(x => x !== e))} className="p-0.5 rounded hover:bg-secondary" aria-label={"Quitar " + e}>
                        <X size={10} className="text-muted-foreground" />
                      </button>
                    </span>
                  );
                })}
              </div>
              <div className="flex items-center gap-2 mt-2">
                <div className="relative flex-1">
                  <input value={manual} onChange={e => setManual(e.target.value)}
                    onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); addManual(); } }}
                    placeholder="correo@empresa.com y Enter" className={inputCls + " font-mono text-xs"} />
                </div>
                <GhostBtn onClick={addManual}><Plus size={13} />Añadir</GhostBtn>
                <div className="relative">
                  <GhostBtn onClick={() => setPicker(p => !p)}><Users size={13} />Contactos<ChevronDown size={12} /></GhostBtn>
                  {picker && (
                    <>
                      <div className="fixed inset-0 z-40" onClick={() => setPicker(false)} />
                      <div className="absolute right-0 top-full mt-1 z-50 w-72 max-h-64 overflow-y-auto rounded-xl border border-border bg-popover shadow-2xl py-1">
                        {CONTACTS.map(c => {
                          const on = to.includes(c.email);
                          return (
                            <button key={c.email} onClick={() => on ? setTo(l => l.filter(x => x !== c.email)) : addTo(c.email)}
                              className="w-full flex items-center gap-2.5 px-3 py-2 text-left hover:bg-secondary transition-colors">
                              <span className={`w-4 h-4 rounded flex items-center justify-center border shrink-0 ${on ? "bg-[#0F9D6E] border-[#0F9D6E]" : "border-border"}`}>
                                {on && <Check size={10} className="text-white" />}
                              </span>
                              <span className="min-w-0">
                                <span className="block text-xs text-foreground truncate">{c.name} · {c.company}</span>
                                <span className="block text-xs text-muted-foreground font-mono truncate">{c.email}</span>
                              </span>
                            </button>
                          );
                        })}
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>

            <div>
              <div className="text-xs text-muted-foreground mb-1.5">Cuándo se envía</div>
              <div className="flex gap-2">
                {([["now", "Enviar ahora", Send], ["later", "Programar", CalendarClock]] as const).map(([m, label, Icon]) => (
                  <button key={m} onClick={() => setMode(m as any)}
                    className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-sm font-medium border transition-colors ${mode === m ? "bg-[#0F9D6E]/10 border-[#0F9D6E] text-[#0F9D6E]" : "border-border text-muted-foreground hover:text-foreground hover:bg-secondary"}`}>
                    <Icon size={14} />{label}
                  </button>
                ))}
              </div>
              {mode === "later" && (
                <div className="grid grid-cols-2 gap-3 mt-3">
                  <Field label="Fecha"><input type="date" className={inputCls} value={date} onChange={e => setDate(e.target.value)} /></Field>
                  <Field label="Hora"><input type="time" className={inputCls} value={time} onChange={e => setTime(e.target.value)} /></Field>
                </div>
              )}
            </div>

            <div>
              <div className="text-xs text-muted-foreground mb-1.5">Adjuntos (PDF)</div>
              <div className="rounded-lg border border-border bg-secondary/40 p-2 min-h-[44px] flex flex-wrap gap-1.5">
                {attachments.length === 0 && <span className="text-xs text-muted-foreground px-1 py-1">Sin PDF adjuntos</span>}
                {attachments.map((a, i) => (
                  <span key={a.name + i} className="inline-flex items-center gap-1.5 pl-2 pr-1 py-1 rounded-md bg-[#EF4444]/10 border border-[#EF4444]/25 text-xs text-foreground">
                    <Paperclip size={10} className="text-[#EF4444]" />
                    <span className="truncate max-w-[160px]">{a.name}</span>
                    <span className="text-muted-foreground">· {a.size}</span>
                    <button onClick={() => setAttachments(l => l.filter((_, j) => j !== i))} className="p-0.5 rounded hover:bg-secondary" aria-label={"Quitar " + a.name}>
                      <X size={10} className="text-muted-foreground" />
                    </button>
                  </span>
                ))}
              </div>
              <label className="inline-flex items-center gap-2 mt-2 px-3 py-1.5 rounded-lg border border-border text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-secondary cursor-pointer transition-colors">
                <Paperclip size={13} />Adjuntar PDF
                <input type="file" accept="application/pdf,.pdf" multiple className="hidden" onChange={e => { addAttachments(e.target.files); e.target.value = ""; }} />
              </label>
            </div>

            <div className="pt-3 border-t border-border flex flex-wrap items-center gap-2">
              <GhostBtn onClick={() => submit("draft")}><Save size={13} />Guardar borrador</GhostBtn>
              <div className="flex-1" />
              <PrimaryBtn onClick={() => submit(mode === "now" ? "sent" : "scheduled")}>
                {mode === "now" ? <><Send size={14} />Enviar a {to.length || 0}</> : <><Clock size={14} />Programar envío</>}
              </PrimaryBtn>
            </div>
          </Card>

          <Card className="p-0 flex flex-col overflow-hidden" >
            <div className="h-11 shrink-0 border-b border-border flex items-center justify-between px-4">
              <div className="flex items-center gap-2 min-w-0">
                <Eye size={13} className="text-muted-foreground shrink-0" />
                <span className="text-xs text-muted-foreground truncate">{tpl?.name ?? "Sin plantilla"}</span>
              </div>
              <div className="flex rounded-lg border border-border overflow-hidden shrink-0">
                <button onClick={() => setDevice("desktop")} title="Escritorio"
                  className={`px-2.5 py-1.5 transition-colors ${device === "desktop" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}><Monitor size={12} /></button>
                <button onClick={() => setDevice("mobile")} title="Móvil"
                  className={`px-2.5 py-1.5 transition-colors ${device === "mobile" ? "bg-[#0F9D6E] text-white" : "text-muted-foreground hover:text-foreground hover:bg-secondary"}`}><Smartphone size={12} /></button>
              </div>
            </div>
            <div className="px-4 py-3 border-b border-border space-y-1">
              <div className="flex gap-2 text-xs"><span className="text-muted-foreground w-16 shrink-0">De</span><span className="font-mono text-foreground truncate">{from}</span></div>
              <div className="flex gap-2 text-xs"><span className="text-muted-foreground w-16 shrink-0">Para</span><span className="text-foreground truncate">{to.length ? to.join(", ") : "—"}</span></div>
              <div className="flex gap-2 text-xs"><span className="text-muted-foreground w-16 shrink-0">Asunto</span><span className="text-foreground truncate">{subject || "(sin asunto)"}</span></div>
              {attachments.length > 0 && (
                <div className="flex gap-2 text-xs"><span className="text-muted-foreground w-16 shrink-0">Adjuntos</span>
                  <span className="text-foreground truncate">{attachments.map(a => a.name).join(", ")}</span></div>
              )}
              <div className="flex gap-2 text-xs"><span className="text-muted-foreground w-16 shrink-0">Salida</span>
                <span className="text-foreground">{mode === "now" ? "Inmediata al confirmar" : `Programada · ${date} ${time}`}</span></div>
            </div>
            <div className="flex-1 min-h-[420px] bg-muted/30 overflow-auto p-5 flex justify-center">
              <PreviewFrame html={html} width={device === "desktop" ? 600 : 390} />
            </div>
          </Card>
        </div>
      ) : (
        <TWrap>
          <thead>
            <tr>
              <TH>Asunto</TH><TH>Plantilla</TH><TH>Destinatarios</TH><TH>Estado</TH>
              <TH>Fecha</TH><TH>Apertura</TH><TH>Responsable</TH><TH>Acciones</TH>
            </tr>
          </thead>
          <tbody>
            {sends.map(s => (
              <tr key={s.id} className="border-b border-border last:border-0 hover:bg-secondary/20 transition-colors">
                <TD>
                  <div className="flex items-center gap-2.5">
                    <div className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0"
                      style={{ backgroundColor: s.status === "scheduled" ? "#3B82F622" : s.status === "failed" ? "#EF444422" : "#0F9D6E22" }}>
                      {s.status === "scheduled" ? <Clock size={13} style={{ color: "#3B82F6" }} />
                        : s.status === "failed" ? <AlertTriangle size={13} style={{ color: "#EF4444" }} />
                        : <Mail size={13} className="text-[#0F9D6E]" />}
                    </div>
                    <span className="font-medium text-foreground">{s.subject}</span>
                    {(s.attachments?.length ?? 0) > 0 && <Paperclip size={11} className="text-muted-foreground shrink-0" />}
                  </div>
                </TD>
                <TD><span className="text-xs text-muted-foreground">{s.template}</span></TD>
                <TD mono>{s.to.length}</TD>
                <TD><SBadge status={s.status} /></TD>
                <TD mono>{s.when}</TD>
                <TD mono>{s.status === "sent" ? Math.round((Math.min(s.opens, s.to.length) / Math.max(1, s.to.length)) * 100) + "%" : "—"}</TD>
                <TD><span className="text-xs text-muted-foreground">{s.owner}</span></TD>
                <TD>
                  <div className="flex items-center gap-0.5">
                    <button onClick={() => setRec(detailOf(s))} title="Ver detalle"
                      className="p-1.5 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors"><Eye size={13} /></button>
                    {s.status === "scheduled" && (
                      <button onClick={() => setSends(l => l.map(x => x.id === s.id ? { ...x, status: "cancelled_send" } : x))}
                        title="Cancelar programación" className="p-1.5 rounded-md text-muted-foreground hover:text-amber-400 hover:bg-secondary transition-colors"><X size={13} /></button>
                    )}
                    <button onClick={() => { setSubject(s.subject); setTo([...s.to]); setFrom(s.from); setTab("Nuevo envío"); }}
                      title="Duplicar en un nuevo envío" className="p-1.5 rounded-md text-muted-foreground hover:text-[#0F9D6E] hover:bg-secondary transition-colors"><Copy size={13} /></button>
                    <button onClick={() => setSends(l => l.filter(x => x.id !== s.id))} title="Eliminar"
                      className="p-1.5 rounded-md text-muted-foreground hover:text-red-400 hover:bg-secondary transition-colors"><Trash2 size={13} /></button>
                  </div>
                </TD>
              </tr>
            ))}
          </tbody>
        </TWrap>
      )}

      <RecordModal rec={rec} onClose={() => setRec(null)} />
    </div>
  );
}

