const NAV = [
  { id: "home",         label: "Inicio",        icon: HomeIcon },
  { id: "sep-agency",   label: "Agencia",       separator: true },
  { id: "dashboard",    label: "Dashboard",     icon: LayoutDashboard },
  { id: "chats",        label: "Chats",         icon: MessageSquare, locked: true, soon: true },
  { id: "myspace",      label: "Mi espacio",    icon: CheckCircle },
  { id: "calendar",     label: "Calendario",    icon: Calendar },
  { id: "crm",          label: "Clientes", icon: Users },
  { id: "services",     label: "Servicios",     icon: Briefcase },
  { id: "sep-brand",    label: "Marca",         separator: true, brand: true },
  { id: "identity",     label: "Identidad de marca", icon: Sparkles },
  { id: "audience",     label: "Audiencia",     icon: Users },
  { id: "seoplan",      label: "SEO Plan", icon: TrendingUp },
  { id: "content",      label: "Content Manager", icon: FileText },
  { id: "projects",     label: "Proyectos", icon: Briefcase },
  { id: "metrics",      label: "Métricas", icon: Activity },
  { id: "ads-soon",     label: "Ads",           icon: Megaphone, locked: true, soon: true },
  { id: "seo",          label: "Módulo SEO",    icon: Search },
  { id: "keywords",     label: "Keywords",      icon: Key },
  { id: "ads",          label: "Módulo Ads",    icon: Megaphone },
  { id: "dev",          label: "Desarrollo",    icon: Code2 },
  { id: "finance",      label: "Finanzas",      icon: DollarSign },
  { id: "files",        label: "Archivos",      icon: FolderOpen },
  { id: "templates",    label: "Plantillas de Correo", icon: LayoutTemplate },
  { id: "emails",       label: "Enviar Correo",  icon: Send },
  { id: "users",        label: "Usuarios",      icon: UserPlus },
  { id: "roles",        label: "Roles",         icon: Shield },
  { id: "integrations", label: "Integraciones", icon: Plug2, locked: true },
] as const;

// Módulos ocultos del menú por ahora (siguen en el código; quita el id de aquí para mostrarlos).
const HIDDEN_NAV = new Set(["seo", "keywords", "ads", "dev", "finance", "files", "templates", "emails", "users", "roles", "integrations"]);

function Sidebar({ active, setActive, onExit }: { active: ModuleId; setActive: (m: ModuleId) => void; onExit: () => void }) {
  const [brandOpen, setBrandOpen] = useState(false);
  const [brand, setBrandState] = useState<string>(() => {
    try { const v = localStorage.getItem("agencyos-brand"); if (v) return v; } catch {}
    return CLIENTS[0].company;
  });
  const setBrand = (v: string) => { setBrandState(v); try { localStorage.setItem("agencyos-brand", v); } catch {} try { window.dispatchEvent(new Event("agencyos-brand")); } catch {} };
  const [custom, setCustom] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem("agencyos-brands") || "[]"); } catch { return []; } });
  const [creating, setCreating] = useState(false);
  const [newBrand, setNewBrand] = useState("");
  const brands = [...CLIENTS.map(c => c.company), ...custom];
  const addBrand = () => {
    const n = newBrand.trim();
    if (!n) return;
    if (!brands.some(b => b.toLowerCase() === n.toLowerCase())) {
      const next = [...custom, n];
      setCustom(next);
      try { localStorage.setItem("agencyos-brands", JSON.stringify(next)); } catch {}
    }
    setBrand(brands.find(b => b.toLowerCase() === n.toLowerCase()) || n);
    setNewBrand(""); setCreating(false); setBrandOpen(false);
  };
  return (
    <aside className="w-52 shrink-0 flex flex-col border-r border-border" style={{ backgroundColor: "var(--sidebar)" }}>
      <div className="px-4 py-4 border-b border-border">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-lg bg-[#0F9D6E] flex items-center justify-center shrink-0">
            <Activity size={13} className="text-white" />
          </div>
          <div>
            <div className="text-sm font-semibold text-foreground leading-none">AgencyOS</div>
          </div>
        </div>
      </div>

      <nav className="flex-1 py-3 overflow-y-auto">
        <div className="px-2 space-y-0.5">
          {NAV.map((item) => {
            if (HIDDEN_NAV.has(item.id)) return null;
            if ("brand" in item) return (
              <div key={item.id} className="relative mb-1" style={{ marginTop: 24 }}>
                <div className="px-2.5 pb-1.5 flex items-center gap-2">
                  <span className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">{item.label}</span>
                  <span className="flex-1 h-px bg-border" />
                </div>
                <button onClick={() => setBrandOpen(o => !o)}
                  className="w-full flex items-center gap-2.5 px-2.5 py-2 rounded-xl bg-secondary/40 border border-border hover:bg-secondary/70 transition-colors">
                  <span className="w-6 h-6 rounded-lg bg-[#0F9D6E]/20 flex items-center justify-center shrink-0"><Building2 size={13} className="text-[#0F9D6E]" /></span>
                  <span className="flex-1 text-left text-sm font-semibold text-foreground leading-none truncate">{brand}</span>
                  <ChevronDown size={14} className={`text-muted-foreground transition-transform ${brandOpen ? "rotate-180" : ""}`} />
                </button>
                {brandOpen && (
                  <div className="absolute left-0 right-0 top-full mt-1.5 z-20 rounded-xl border border-border bg-popover shadow-xl p-1.5">
                    <div className="max-h-56 overflow-y-auto space-y-0.5">
                      {brands.map(name => {
                        const on = brand === name;
                        return (
                          <button key={name} onClick={() => { setBrand(name); setBrandOpen(false); setCreating(false); }}
                            className={`w-full flex items-center gap-2.5 px-2 py-2 rounded-lg text-sm text-left transition-colors ${on ? "text-[#0F9D6E] font-medium" : "text-foreground hover:bg-secondary"}`}>
                            <span className={`w-6 h-6 rounded-md flex items-center justify-center text-[11px] font-bold shrink-0 ${on ? "bg-[#0F9D6E]/20 text-[#0F9D6E]" : "bg-secondary text-muted-foreground"}`}>{name.charAt(0).toUpperCase()}</span>
                            <span className="flex-1 truncate">{name}</span>
                            {on && <Check size={14} />}
                          </button>
                        );
                      })}
                    </div>
                    <div className="border-t border-border mt-1.5 pt-1.5">
                      {creating ? (
                        <div className="flex items-center gap-1.5 px-1">
                          <input autoFocus value={newBrand} onChange={e => setNewBrand(e.target.value)}
                            onKeyDown={e => { if (e.key === "Enter") addBrand(); if (e.key === "Escape") { setCreating(false); setNewBrand(""); } }}
                            placeholder="Nombre de la marca" className="flex-1 min-w-0 px-2 py-1.5 bg-secondary/40 border border-border rounded-lg text-sm text-foreground placeholder-muted-foreground focus:outline-none focus:border-[#0F9D6E]" />
                          <button onClick={addBrand} disabled={!newBrand.trim()} className="p-1.5 rounded-lg bg-[#0F9D6E] text-white disabled:opacity-40"><Check size={13} /></button>
                        </div>
                      ) : (
                        <button onClick={() => setCreating(true)} className="w-full flex items-center gap-2.5 px-2 py-2 rounded-lg text-sm text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors">
                          <span className="w-6 h-6 flex items-center justify-center shrink-0"><Plus size={14} /></span>Crear marca
                        </button>
                      )}
                    </div>
                  </div>
                )}
              </div>
            );
            if ("separator" in item) return (
              <div key={item.id} className="px-2.5 pt-4 pb-1.5 flex items-center gap-2">
                <span className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">{item.label}</span>
                <span className="flex-1 h-px bg-border" />
              </div>
            );
            const isActive = active === item.id;
            const isLocked = "locked" in item;
            return (
              <button key={item.id}
                onClick={() => !isLocked && setActive(item.id as ModuleId)}
                className={`w-full flex items-center gap-2.5 px-2.5 py-2 rounded-lg text-sm transition-all relative ${
                  isActive  ? "bg-[#0F9D6E]/15 text-[#0F9D6E] font-medium" :
                  isLocked  ? "text-muted-foreground/35 cursor-not-allowed" :
                               "text-muted-foreground hover:bg-secondary hover:text-foreground"
                }`}>
                <item.icon size={14} />
                <span className="flex-1 text-left leading-none">{item.label}</span>
                {"soon" in item ? <span className="text-[9px] font-medium uppercase tracking-wide px-1.5 py-0.5 rounded-full bg-secondary text-muted-foreground">Próximamente</span> : isLocked ? <Lock size={10} className="text-muted-foreground/35" /> : null}
                {isActive && <span className="absolute right-0 top-1/2 -translate-y-1/2 w-0.5 h-4 bg-[#0F9D6E] rounded-l-full" />}
              </button>
            );
          })}
        </div>
      </nav>

      <div className="border-t border-border">
        <button onClick={onExit}
          className="w-full flex items-center gap-2 px-4 py-2.5 text-xs text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors border-b border-border">
          <ChevronLeft size={12} />
          Volver al sitio
        </button>
        <div className="p-3 flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-full bg-[#0F9D6E]/20 flex items-center justify-center shrink-0">
            <span className="text-xs font-bold text-[#0F9D6E]">AM</span>
          </div>
          <div className="min-w-0 flex-1">
            <div className="text-xs font-medium text-foreground truncate">Adriana Martínez</div>
            <div className="text-xs text-muted-foreground">Administrador</div>
          </div>
        </div>
      </div>
    </aside>
  );
}

