const MODULE_COMPONENTS: Record<ModuleId, () => JSX.Element> = {
  home: HomeModule, myspace: MySpaceModule, calendar: CalendarModule, identity: IdentityModule, audience: AudienceModule, seoplan: SeoPlanModule, content: ContentModule, projects: ProjectsModule, metrics: MetricsModule, dashboard: DashboardModule, crm: CRMModule, services: ServicesModule,
  seo: SEOModule, keywords: KeywordsModule, ads: AdsModule, dev: DevModule,
  finance: FinanceModule, files: FilesModule,
  templates: TemplatesModule, emails: SendModule, users: UsersModule,
  roles: RolesModule, integrations: IntegrationsModule,
};

// Vista de un solo módulo, sin sidebar — para abrir cada módulo por separado.
export function AgencyModule({ id }: { id: ModuleId }) {
  const [theme, setTheme] = useState<"dark" | "light">(() => {
    try { return localStorage.getItem("agencyos-theme") === "light" ? "light" : "dark"; } catch { return "dark"; }
  });
  useTokenStyles();
  LIGHT_MODE = theme === "light";
  useEffect(() => { try { localStorage.setItem("agencyos-theme", theme); } catch {} }, [theme]);

  const Mod = MODULE_COMPONENTS[id] || DashboardModule;

  return (
    <div id="agencyos-root" data-theme={theme} className="flex flex-col h-screen overflow-hidden bg-background text-foreground" style={theme === "dark" ? DARK_THEME : LIGHT_THEME}>
      <header className="h-11 border-b border-border flex items-center justify-between px-5 shrink-0" style={{ backgroundColor: "var(--sidebar)" }}>
        <div className="flex items-center gap-3">
          <div className="w-5 h-5 rounded bg-[#0F9D6E] flex items-center justify-center">
            <span className="text-[10px] font-bold text-white">R</span>
          </div>
          <span className="text-xs font-semibold text-foreground">{MODULE_LABELS[id]}</span>
          <span className="text-[10px] text-muted-foreground">módulo independiente</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
            title={theme === "dark" ? "Cambiar a modo claro" : "Cambiar a modo oscuro"}
            className="p-1.5 rounded-lg hover:bg-secondary transition-colors">
            {theme === "dark" ? <Sun size={14} style={{ color: "#64748B" }} /> : <Moon size={14} style={{ color: "#64748B" }} />}
          </button>
          <div className="w-6 h-6 rounded-full bg-[#0F9D6E]/20 flex items-center justify-center">
            <span className="text-xs font-bold text-[#0F9D6E]">AM</span>
          </div>
        </div>
      </header>
      <main className="flex-1 overflow-y-auto p-5 lg:p-6">
        <Mod />
      </main>
    </div>
  );
}

export default function AgencyDashboard({ onExit }: { onExit: () => void }) {
  const [active, setActive] = useState<ModuleId>("home");
  GO_TO = setActive;
  const [theme, setTheme] = useState<"dark" | "light">(() => {
    try { return localStorage.getItem("agencyos-theme") === "light" ? "light" : "dark"; } catch { return "dark"; }
  });
  useTokenStyles();
  LIGHT_MODE = theme === "light";
  useEffect(() => { try { localStorage.setItem("agencyos-theme", theme); } catch {} }, [theme]);

  const MODULES: Record<ModuleId, ReactNode> = {
    home:         <HomeModule />,
    myspace:      <MySpaceModule />,
    calendar:     <CalendarModule />,
    identity:     <IdentityModule />,
    audience:     <AudienceModule />,
    seoplan:      <SeoPlanModule />,
    content:      <ContentModule />,
    projects:     <ProjectsModule />,
    metrics:      <MetricsModule />,
    dashboard:    <DashboardModule />,
    crm:          <CRMModule />,
    services:     <ServicesModule />,
    seo:          <SEOModule />,
    keywords:     <KeywordsModule />,
    ads:          <AdsModule />,
    dev:          <DevModule />,
    finance:      <FinanceModule />,
    files:        <FilesModule />,
    templates:    <TemplatesModule />,
    emails:       <SendModule />,
    users:        <UsersModule />,
    roles:        <RolesModule />,
    integrations: <IntegrationsModule />,
  };

  return (
    <div id="agencyos-root" data-theme={theme} className="flex h-screen overflow-hidden bg-background text-foreground" style={theme === "dark" ? DARK_THEME : LIGHT_THEME}>
      <Sidebar active={active} setActive={setActive} onExit={onExit} />
      <div className="flex-1 flex flex-col overflow-hidden">
        <main className="flex-1 overflow-y-auto p-5 lg:p-6">
          {MODULES[active]}
        </main>
      </div>
    </div>
  );
}
